window.LEVEL_DATA = window.LEVEL_DATA || {};
window.LEVEL_DATA["B1"] = {"ai-02":{"intro":"Kuruluş hikâyeni anlatıyorsun: sorun, fikir, ekip ve misyon.","text":[{"en":"About one in five people in the world, over a billion in total, has some hearing loss.","tr":"Dünyada her beş kişiden biri, yani toplamda bir milyardan fazla insan, bir miktar işitme kaybı yaşıyor."},{"en":"However, most of them have never had a hearing test.","tr":"Ancak bunların çoğu hiç işitme testi yaptırmadı."},{"en":"The main reason is simple: there aren't enough audiologists.","tr":"Asıl neden basit: yeterli odyolog yok."},{"en":"In small towns, people often have to wait months for an appointment.","tr":"Küçük kasabalarda insanlar bir randevu için çoğu zaman aylarca beklemek zorunda kalıyor."},{"en":"When we saw this, we asked ourselves a simple question.","tr":"Bunu görünce kendimize basit bir soru sorduk."},{"en":"What if a machine could do the test without an expert in the room?","tr":"Ya bir makine bu testi odada bir uzman olmadan yapabilseydi?"},{"en":"That question became AIHEAR, and it has guided everything we've done since.","tr":"O soru AIHEAR'a dönüştü ve o günden beri yaptığımız her şeye yön verdi."},{"en":"Today we are a team of six: three engineers, one doctor and two business people.","tr":"Bugün altı kişilik bir ekibiz: üç mühendis, bir doktor ve iki iş insanı."},{"en":"Our mission is to make hearing tests accessible to everyone, everywhere.","tr":"Misyonumuz işitme testlerini herkes için, her yerde erişilebilir kılmak."},{"en":"That's why, although we started in Turkey, we've always seen our market as global.","tr":"Bu yüzden Türkiye'de başlamış olsak da pazarımızı her zaman küresel olarak gördük."}],"vocab":[{"en":"hearing loss","tr":"işitme kaybı","ex":"One in five people has some hearing loss.","def":"when a person cannot hear as well as normal"},{"en":"audiologist","tr":"odyolog","ex":"There aren't enough audiologists.","def":"a specialist who tests and treats hearing problems"},{"en":"wait months for","tr":"...için aylarca beklemek","ex":"People wait months for an appointment.","def":"to wait a very long time for something"},{"en":"appointment","tr":"randevu","ex":"It's hard to get an appointment in a small town.","def":"a fixed time to see a doctor or other professional"},{"en":"What if...?","tr":"Ya ... olsaydı?","ex":"What if a machine could do the test?","def":"used to imagine a possible situation"},{"en":"guide","tr":"yön vermek","ex":"That question has guided everything we've done.","def":"to influence or direct someone's decisions"},{"en":"accessible","tr":"erişilebilir","ex":"We want to make hearing tests accessible to everyone.","def":"easy to get or use"},{"en":"see something as","tr":"...olarak görmek","ex":"We've always seen our market as global.","def":"to think of something in a particular way"}],"grammar":{"title":"Present perfect vs past simple","tr":"Geçmişte belirli bir anda olan olaylar için past simple kullanılır (We started in Turkey). Şimdiye kadarki deneyimler ve bugüne uzanan durumlar için present perfect kullanılır (Most of them have never had a test).","examples":["Most of them have never had a hearing test.","When we saw this, we asked a simple question.","That question has guided everything we've done since."]},"questions":[{"q":"What is the main reason people don't get tested?","options":["The test is too expensive","There aren't enough audiologists","People don't care about hearing"],"a":1},{"q":"What problem do people in small towns have?","options":["They wait months for an appointment","They have no doctors at all","They have to travel abroad"],"a":0},{"q":"Who is in the AIHEAR team?","options":["Six engineers","Two doctors and four engineers","Three engineers, one doctor and two business people"],"a":2},{"q":"How does the company see its market?","options":["As only Turkish","As global","As only European"],"a":1}],"gaps":[{"s":"Most of them have never ___ a hearing test.","a":"had","hint":"yaptırmak (V3)"},{"s":"The main reason is simple: there aren't enough ___.","a":"audiologists","hint":"odyolog"},{"s":"Our mission is to make hearing tests ___ to everyone.","a":"accessible","hint":"erişilebilir"}],"order":[{"a":"What if a machine could do the test?"},{"a":"Most of them have never had a hearing test."}],"translate":[{"tr":"Çoğu insan hiç işitme testi yaptırmadı.","en":"Most people have never had a hearing test.","keys":["never had","hearing test"]},{"tr":"Pazarımızı her zaman küresel olarak gördük.","en":"We have always seen our market as global.","keys":["always seen","market","global"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir teknoloji gazetecisi röportaj için AIHEAR'ın kuruluş hikâyesini soruyor.","turns":[{"ai":"Why did you start AIHEAR? What problem did you see?","aiTr":"AIHEAR'ı neden kurdunuz? Nasıl bir sorun gördünüz?","hint":"One in five people has some hearing loss, but most of them have never had a test because there aren't enough audiologists.","keys":["hearing loss","never had","audiologists"]},{"ai":"Is it really that hard to get a test?","aiTr":"Test yaptırmak gerçekten o kadar zor mu?","hint":"Yes, in small towns people often have to wait months for an appointment.","keys":["small towns","months","appointment"]},{"ai":"So where did the idea come from?","aiTr":"Peki fikir nereden çıktı?","hint":"We asked ourselves: what if a machine could do the test without an expert?","keys":["what if","machine","without an expert"]},{"ai":"And what's your mission today?","aiTr":"Peki bugünkü misyonunuz ne?","hint":"Our mission is to make hearing tests accessible to everyone, everywhere.","keys":["mission","accessible","everyone"]}]}},"ai-01":{"intro":"Cihazının nasıl çalıştığını sıralama ifadeleriyle net bir şekilde anlatıyorsun.","text":[{"en":"An audiometer is a device that measures how well a person can hear.","tr":"Odyometre, bir kişinin ne kadar iyi duyabildiğini ölçen bir cihazdır."},{"en":"Normally, an expert has to do the test in a quiet room, and it takes about thirty minutes.","tr":"Normalde testi sessiz bir odada bir uzmanın yapması gerekir ve yaklaşık otuz dakika sürer."},{"en":"Our audiometer is autonomous, which means it can run the whole test by itself.","tr":"Bizim odyometremiz otonom, yani tüm testi kendi başına yürütebiliyor."},{"en":"First, the patient puts on the headphones and follows the instructions on the screen.","tr":"Önce hasta kulaklıkları takar ve ekrandaki talimatları takip eder."},{"en":"The device then plays sounds at different volumes and frequencies.","tr":"Ardından cihaz farklı ses seviyelerinde ve frekanslarda sesler çalar."},{"en":"Every time the patient hears a sound, they press a button.","tr":"Hasta her ses duyduğunda bir düğmeye basar."},{"en":"Our AI analyses each answer and adjusts the next sound in real time.","tr":"Yapay zekâmız her cevabı analiz eder ve bir sonraki sesi gerçek zamanlı olarak ayarlar."},{"en":"In the end, the device produces an audiogram, which is a chart of the patient's hearing.","tr":"Sonunda cihaz, hastanın işitmesini gösteren bir grafik olan odyogramı oluşturur."},{"en":"The whole test takes less than ten minutes, and there's no need for an expert in the room.","tr":"Tüm test on dakikadan kısa sürer ve odada bir uzmana gerek yoktur."},{"en":"The AI runs on the device itself, so patient data stays private and it even works without internet.","tr":"Yapay zekâ doğrudan cihazın üzerinde çalışır; bu yüzden hasta verileri gizli kalır ve cihaz internet olmadan da çalışır."}],"vocab":[{"en":"measure","tr":"ölçmek","ex":"The device measures how well a person can hear.","def":"to find the size, amount or level of something"},{"en":"run a test","tr":"test yapmak, yürütmek","ex":"The device runs the whole test by itself.","def":"to carry out a test from start to finish"},{"en":"follow the instructions","tr":"talimatları takip etmek","ex":"The patient follows the instructions on the screen.","def":"to do what the instructions say"},{"en":"frequency","tr":"frekans","ex":"The device plays sounds at different frequencies.","def":"how high or low a sound is"},{"en":"adjust","tr":"ayarlamak","ex":"The AI adjusts the next sound in real time.","def":"to change something slightly so it works better"},{"en":"in real time","tr":"gerçek zamanlı olarak","ex":"The test changes in real time.","def":"immediately, while something is happening"},{"en":"there's no need for","tr":"...e gerek yok","ex":"There's no need for an expert in the room.","def":"used to say that something is not necessary"},{"en":"stay private","tr":"gizli kalmak","ex":"Patient data stays private.","def":"to not be seen or shared by other people"}],"grammar":{"title":"Sequencing words: first, then, every time, in the end","tr":"Bir süreci adım adım anlatırken sıralama ifadeleri kullan: first (önce), then (sonra), every time (her ...-diğinde), in the end (sonunda). Dinleyicinin süreci takip etmesini kolaylaştırır.","examples":["First, the patient puts on the headphones.","The device then plays sounds at different frequencies.","In the end, the device produces an audiogram."]},"questions":[{"q":"How is a normal hearing test usually done?","options":["By the patient at home","By an expert in a quiet room","By a computer in a hospital"],"a":1},{"q":"What does the AI do in real time?","options":["It adjusts the next sound","It calls the doctor","It prints the audiogram"],"a":0},{"q":"What is an audiogram?","options":["A type of headphones","A sound the device plays","A chart of the patient's hearing"],"a":2},{"q":"Why does patient data stay private?","options":["The test is very short","The AI runs on the device itself","An expert checks it"],"a":1}],"gaps":[{"s":"Our AI ___ the next sound in real time.","a":"adjusts","hint":"ayarlar"},{"s":"There's no ___ for an expert in the room.","a":"need","hint":"gerek"},{"s":"The AI runs on the device ___, so patient data stays private.","a":"itself","hint":"kendisi"}],"order":[{"a":"Every time the patient hears a sound they press a button."},{"a":"The device produces an audiogram at the end."}],"translate":[{"tr":"Hasta ekrandaki talimatları takip eder.","en":"The patient follows the instructions on the screen.","keys":["follows the instructions","screen"]},{"tr":"Hasta verileri gizli kalır.","en":"Patient data stays private.","keys":["patient data","stays private"]}],"roleplay":{"persona":"Curious doctor","personaTr":"Meraklı doktor","scene":"Bir fuarda, standına gelen İngiliz bir kulak burun boğaz doktoru cihazın nasıl çalıştığını soruyor.","turns":[{"ai":"This looks interesting. What exactly does it do?","aiTr":"İlginç görünüyor. Tam olarak ne yapıyor?","hint":"It's an autonomous audiometer, which means it can run a full hearing test by itself.","keys":["autonomous","audiometer","by itself"]},{"ai":"So how does the patient actually use it?","aiTr":"Peki hasta onu nasıl kullanıyor?","hint":"First, they put on the headphones. Then, every time they hear a sound, they press a button.","keys":["headphones","press a button","every time"]},{"ai":"And what does the AI do during the test?","aiTr":"Peki test sırasında yapay zekâ ne yapıyor?","hint":"It analyses each answer and adjusts the next sound in real time.","keys":["adjusts","real time","analyses"]},{"ai":"What about patient data? Do you send it to the cloud?","aiTr":"Peki hasta verileri? Buluta mı gönderiyorsunuz?","hint":"No, the AI runs on the device itself, so the data stays private.","keys":["on the device","private"]}]}},"st-02":{"intro":"Küçük bir ekibi yönetirken öğrendiklerini ve günlük çalışma düzenini anlatıyorsun.","text":[{"en":"Managing a small team of six isn't easy, but I've learned a lot since we started.","tr":"Altı kişilik küçük bir ekibi yönetmek kolay değil ama başladığımızdan beri çok şey öğrendim."},{"en":"Every Monday morning, we have a short meeting where everyone shares three things.","tr":"Her pazartesi sabahı herkesin üç şey paylaştığı kısa bir toplantı yaparız."},{"en":"They say what they did last week, what they're going to do this week and what's blocking them.","tr":"Geçen hafta ne yaptıklarını, bu hafta ne yapacaklarını ve onları neyin engellediğini söylerler."},{"en":"I've found that clear tasks with clear deadlines save everyone a lot of time.","tr":"Net son tarihleri olan net görevlerin herkese çok zaman kazandırdığını gördüm."},{"en":"Instead of 'Can you look at the report?', I say 'Please finish the test report by Friday.'","tr":"'Rapora bakabilir misin?' yerine 'Lütfen test raporunu cumaya kadar bitir.' derim."},{"en":"When something goes wrong, we try to solve it together instead of looking for someone to blame.","tr":"Bir şeyler ters gittiğinde suçlayacak birini aramak yerine birlikte çözmeye çalışırız."},{"en":"I also give feedback often, and I try to make it honest but kind.","tr":"Ayrıca sık sık geri bildirim veririm ve bunu dürüst ama nazik bir şekilde yapmaya çalışırım."},{"en":"However, the most important thing I've learned is that a good leader should listen more than they talk.","tr":"Ancak öğrendiğim en önemli şey, iyi bir liderin konuştuğundan daha çok dinlemesi gerektiği."},{"en":"In the end, I have to trust my team, because they know their work better than I do.","tr":"Sonuçta ekibime güvenmek zorundayım, çünkü kendi işlerini benden daha iyi biliyorlar."}],"vocab":[{"en":"what's blocking you","tr":"seni engelleyen şey","ex":"Everyone shares what's blocking them.","def":"the problem that stops you from moving forward"},{"en":"save time","tr":"zaman kazandırmak","ex":"Clear deadlines save everyone a lot of time.","def":"to make something take less time"},{"en":"meet a deadline","tr":"son tarihe yetiştirmek","ex":"Clear tasks help people meet their deadlines.","def":"to finish work by the time it is due"},{"en":"go wrong","tr":"ters gitmek","ex":"When something goes wrong, we solve it together.","def":"to stop working well or have a bad result"},{"en":"instead of","tr":"...yerine","ex":"I say 'Please finish it by Friday' instead of 'Can you look at it?'","def":"in place of something else"},{"en":"look for someone to blame","tr":"suçlayacak birini aramak","ex":"We don't look for someone to blame.","def":"to try to find a person whose fault a problem is"},{"en":"honest but kind","tr":"dürüst ama nazik","ex":"I try to make my feedback honest but kind.","def":"telling the truth in a gentle way"},{"en":"give feedback","tr":"geri bildirim vermek","ex":"I give feedback often.","def":"to tell someone what is good or bad about their work"}],"grammar":{"title":"Present perfect: what I've learned","tr":"'have/has + V3' ile geçmişten bugüne uzanan deneyimleri anlatırız: I've learned, I've found. Ne zaman olduğu değil, bugünkü sonucu önemlidir.","examples":["I've learned a lot since we started.","I've found that clear tasks save everyone a lot of time.","The most important thing I've learned is to listen."]},"questions":[{"q":"What three things does everyone share on Monday?","options":["Their goals, their salary and their holidays","What they did, what they will do and what's blocking them","Their best idea, their worst idea and a question"],"a":1},{"q":"Why does the speaker give tasks with clear deadlines?","options":["Because they save everyone time","Because the team is lazy","Because investors ask for it"],"a":0},{"q":"What happens when something goes wrong?","options":["The speaker blames the engineer","The task is cancelled","The team solves it together"],"a":2},{"q":"What is the most important thing the speaker has learned?","options":["A leader should talk a lot","A leader should listen more than they talk","A leader should work alone"],"a":1}],"gaps":[{"s":"Clear deadlines save everyone a lot of ___.","a":"time","hint":"zaman"},{"s":"When something goes ___, we solve it together.","a":"wrong","hint":"ters gitmek"},{"s":"I try to make my feedback honest but ___.","a":"kind","hint":"nazik"}],"order":[{"a":"We have a short meeting every Monday morning."},{"a":"A good leader should listen more than they talk."}],"translate":[{"tr":"Bir şeyler ters gittiğinde birlikte çözeriz.","en":"When something goes wrong, we solve it together.","keys":["goes wrong","together"]},{"tr":"Başladığımızdan beri çok şey öğrendim.","en":"I've learned a lot since we started.","keys":["learned a lot","since we started"]}],"roleplay":{"persona":"New engineer","personaTr":"Yeni işe başlayan mühendis","scene":"Ekibe bu hafta katılan yeni yazılım mühendisi, nasıl çalıştığınızı ve ondan ne beklediğini soruyor.","turns":[{"ai":"Hi, it's my first week. How does the team usually work?","aiTr":"Merhaba, ilk haftam. Ekip genelde nasıl çalışıyor?","hint":"Every Monday morning we have a short meeting where everyone shares what they did, what they're going to do and what's blocking them.","keys":["Monday","meeting","blocking"]},{"ai":"What should I do if something goes wrong with my task?","aiTr":"Görevimde bir şeyler ters giderse ne yapmalıyım?","hint":"Tell me early, and we'll solve it together. We don't look for someone to blame.","keys":["together","blame","solve"]},{"ai":"How will I know if I'm doing a good job?","aiTr":"İyi iş çıkarıp çıkarmadığımı nasıl anlayacağım?","hint":"I give feedback often, and I try to make it honest but kind.","keys":["feedback","honest","kind"]},{"ai":"OK, so what's my first task?","aiTr":"Tamam, peki ilk görevim ne?","hint":"Please finish the test report by Friday. That's your deadline.","keys":["report","Friday","deadline"]}]}},"te-01":{"intro":"Yapay zekânın sağlıkta getirdiği fırsatları ve riskleri, özellikle teste erişim konusunu anlatıyorsun.","text":[{"en":"AI has already changed the way many hospitals work, and I think this is only the beginning.","tr":"Yapay zekâ pek çok hastanenin çalışma şeklini zaten değiştirdi ve bence bu daha başlangıç."},{"en":"For example, AI can check thousands of X-rays and help doctors find cancer earlier.","tr":"Örneğin yapay zekâ binlerce röntgeni inceleyip doktorların kanseri daha erken bulmasına yardım edebiliyor."},{"en":"Unlike a human, it doesn't get tired, so it can work twenty-four hours a day.","tr":"İnsanın aksine yorulmuyor, bu yüzden günde yirmi dört saat çalışabiliyor."},{"en":"However, AI isn't perfect, because it can make mistakes, especially when the data is poor.","tr":"Ancak yapay zekâ mükemmel değil, çünkü özellikle veri kötü olduğunda hata yapabiliyor."},{"en":"That's why a doctor should always check the final result.","tr":"Bu yüzden nihai sonucu her zaman bir doktor kontrol etmeli."},{"en":"For me, the biggest opportunity is access, because many people never see a specialist.","tr":"Bana göre en büyük fırsat erişim, çünkü pek çok insan hiçbir zaman bir uzmana görünmüyor."},{"en":"About one in five people has some hearing loss, but most have never been tested.","tr":"Yaklaşık her beş kişiden birinde bir miktar işitme kaybı var ama çoğu hiç test edilmedi."},{"en":"In small towns, there aren't enough audiologists, so people often wait months for an appointment.","tr":"Küçük kasabalarda yeterli odyolog yok, bu yüzden insanlar randevu için çoğu zaman aylarca bekliyor."},{"en":"At our company, we use AI so that a hearing test can be done without an expert in the room.","tr":"Şirketimizde yapay zekâyı, işitme testi odada bir uzman olmadan yapılabilsin diye kullanıyoruz."},{"en":"If we can bring tests closer to patients, more people will get help in time.","tr":"Testleri hastalara yaklaştırabilirsek daha çok insan zamanında yardım alacak."}],"vocab":[{"en":"make a mistake","tr":"hata yapmak","ex":"AI can make mistakes when the data is poor.","def":"to do something wrong without wanting to"},{"en":"poor data","tr":"kötü / yetersiz veri","ex":"Poor data leads to poor results.","def":"information that is incomplete or not correct"},{"en":"final result","tr":"nihai sonuç","ex":"A doctor should check the final result.","def":"the last and official outcome of something"},{"en":"opportunity","tr":"fırsat","ex":"The biggest opportunity is access.","def":"a chance to do something good or useful"},{"en":"access","tr":"erişim","ex":"Many people don't have access to a hearing test.","def":"the chance or right to use or get something"},{"en":"hearing loss","tr":"işitme kaybı","ex":"About one in five people has some hearing loss.","def":"a condition in which a person cannot hear well"},{"en":"wait months for","tr":"...için aylarca beklemek","ex":"People often wait months for an appointment.","def":"to wait a very long time for something"},{"en":"in time","tr":"zamanında","ex":"More people will get help in time.","def":"early enough to make a difference"}],"grammar":{"title":"Present perfect: already, never","tr":"Present perfect (have/has + V3), geçmişte başlayıp bugünü etkileyen durumlar için kullanılır. 'already' (zaten) ve 'never' (hiç) ile sık görülür. Pasif hâli: have been + V3 (have never been tested).","examples":["AI has already changed the way many hospitals work.","Most people have never been tested.","Have you ever had a hearing test?"]},"questions":[{"q":"What can AI help doctors find in X-rays?","options":["Broken equipment","Cancer","Hearing loss"],"a":1},{"q":"When is AI more likely to make mistakes?","options":["When the data is poor","At night","When it gets tired"],"a":0},{"q":"What does the speaker see as the biggest opportunity?","options":["Lower prices","Faster computers","Better access to tests"],"a":2},{"q":"Why do people in small towns wait months?","options":["Tests are too expensive","They don't want a test","The devices are broken","There aren't enough audiologists"],"a":3}],"gaps":[{"s":"AI has already ___ the way many hospitals work.","a":"changed","hint":"değiştirdi"},{"s":"Most people with hearing loss have never been ___.","a":"tested","hint":"test edilmek"},{"s":"If we can bring tests closer to patients, more people will get help in ___.","a":"time","hint":"zamanında (in …)"}],"order":[{"a":"A doctor should always check the final result."},{"a":"Many people never see a specialist."}],"translate":[{"tr":"Çoğu insan hiç test edilmedi.","en":"Most people have never been tested.","keys":["have never been tested"]},{"tr":"Bu yüzden sonucu her zaman bir doktor kontrol etmeli.","en":"That's why a doctor should always check the result.","keys":["that's why","should always check"]}],"roleplay":{"persona":"Skeptical doctor","personaTr":"Şüpheci doktor","scene":"Deneyimli bir doktor yapay zekânın hastalara gerçekten ne kazandırdığını soruyor.","turns":[{"ai":"Why do we need AI in a hospital? We have good doctors.","aiTr":"Hastanede neden yapay zekâya ihtiyacımız var? İyi doktorlarımız var.","hint":"AI can check thousands of X-rays, and it doesn't get tired, so it helps doctors find problems earlier.","keys":["thousands","tired","earlier"]},{"ai":"But AI makes mistakes, doesn't it?","aiTr":"Ama yapay zekâ hata yapıyor, değil mi?","hint":"Yes, it can make mistakes, especially when the data is poor. That's why a doctor should always check the final result.","keys":["mistakes","data","check"]},{"ai":"So what's the real benefit for patients?","aiTr":"Peki hastalar için asıl fayda ne?","hint":"Access. About one in five people has some hearing loss, but most have never been tested.","keys":["access","one in five","never been tested"]},{"ai":"How does your device help with that?","aiTr":"Cihazınız bu konuda nasıl yardımcı oluyor?","hint":"A hearing test can be done without an expert in the room, so more people will get help in time.","keys":["without an expert","in time","in the room"]}]}},"te-03":{"intro":"Bir hatayı adım adım bulma ve çözme hikâyeni anlatıyorsun.","text":[{"who":"Me","en":"Last week we had a strange problem with our device.","tr":"Geçen hafta cihazımızla ilgili garip bir sorun yaşadık."},{"who":"Me","en":"In some clinics, the test results were wrong at high frequencies, but in others everything worked perfectly.","tr":"Bazı kliniklerde test sonuçları yüksek frekanslarda yanlış çıktı, ama diğerlerinde her şey kusursuz çalıştı."},{"who":"Me","en":"At first, we guessed it was the headphones, but we were wrong.","tr":"İlk başta sorunun kulaklıklarda olduğunu tahmin ettik, ama yanılmışız."},{"who":"Me","en":"So we collected data from all the devices and compared the clinics with and without problems.","tr":"Bu yüzden tüm cihazlardan veri topladık ve sorun yaşayan kliniklerle yaşamayanları karşılaştırdık."},{"who":"Me","en":"We found out that the problem happened only in rooms with old air conditioners.","tr":"Sorunun yalnızca eski klimaların olduğu odalarda ortaya çıktığını öğrendik."},{"who":"Me","en":"Their noise was too loud at exactly those frequencies, so patients couldn't hear the test sounds.","tr":"Klimaların gürültüsü tam da o frekanslarda çok yüksekti, bu yüzden hastalar test seslerini duyamıyordu."},{"who":"Me","en":"The solution was simple: we added a noise check before the test starts.","tr":"Çözüm basitti: test başlamadan önce bir gürültü kontrolü ekledik."},{"who":"Me","en":"If the room is too noisy, the device warns the user.","tr":"Oda fazla gürültülüyse cihaz kullanıcıyı uyarıyor."},{"who":"Me","en":"Since the update, the results have been correct in every clinic.","tr":"Güncellemeden bu yana sonuçlar her klinikte doğru çıkıyor."},{"who":"Me","en":"We have learned an important lesson: look at the data before you guess.","tr":"Önemli bir ders öğrendik: tahmin etmeden önce verilere bak."}],"vocab":[{"en":"at first","tr":"ilk başta","ex":"At first, we guessed it was the headphones.","def":"at the beginning, before you know more"},{"en":"collect data","tr":"veri toplamak","ex":"We collected data from all the devices.","def":"to gather information so you can study it"},{"en":"compare","tr":"karşılaştırmak","ex":"We compared the clinics with and without problems.","def":"to look at two or more things to see how they are different"},{"en":"find out","tr":"öğrenmek, ortaya çıkarmak","ex":"We found out that the problem happened only in some rooms.","def":"to discover a fact"},{"en":"solution","tr":"çözüm","ex":"The solution was simple.","def":"a way to solve a problem"},{"en":"warn","tr":"uyarmak","ex":"The device warns the user if the room is too noisy.","def":"to tell someone about a possible problem"},{"en":"guess","tr":"tahmin etmek","ex":"Look at the data before you guess.","def":"to give an answer without being sure"},{"en":"learn a lesson","tr":"ders çıkarmak","ex":"We have learned an important lesson.","def":"to understand something useful from an experience"}],"grammar":{"title":"Past simple vs present perfect","tr":"Belirli bir geçmiş zamanda bitmiş olaylar için past simple kullanılır (Last week we had a problem). Geçmişte başlayıp bugüne uzanan durumlar ya da sonucu bugün önemli olan deneyimler için present perfect (have/has + V3) kullanılır.","examples":["Last week we had a strange problem.","Since the update, the results have been correct.","We have learned an important lesson."]},"questions":[{"q":"What was the problem?","options":["The device was too slow","The screen was broken","Results were wrong at high frequencies in some clinics"],"a":2},{"q":"What did they guess at first?","options":["That the headphones were the problem","That the doctors made mistakes","That the software was old"],"a":0},{"q":"What caused the problem?","options":["A software bug","Noise from old air conditioners","Bad headphones"],"a":1},{"q":"What has happened since the update?","options":["The results have been correct in every clinic","Some clinics have stopped using the device","The team has changed all the headphones"],"a":0}],"gaps":[{"s":"So we ___ data from all the devices.","a":"collected","hint":"topladık"},{"s":"The ___ was simple: we added a noise check.","a":"solution","hint":"çözüm"},{"s":"If the room is too noisy, the device ___ the user.","a":"warns","hint":"uyarır"}],"order":[{"a":"Look at the data before you guess."},{"a":"The problem happened only in rooms with old air conditioners."}],"translate":[{"tr":"Çözüm basitti.","en":"The solution was simple.","keys":["solution","simple"]},{"tr":"Güncellemeden bu yana sonuçlar doğru çıkıyor.","en":"Since the update, the results have been correct.","keys":["since the update","have been correct"]}],"roleplay":{"persona":"Clinic manager","personaTr":"Klinik müdürü","scene":"Bir klinik müdürü geçen haftaki sorunun ne olduğunu ve nasıl çözüldüğünü soruyor.","turns":[{"ai":"We heard some clinics had wrong results. What happened?","aiTr":"Bazı kliniklerde yanlış sonuçlar çıktığını duyduk. Ne oldu?","hint":"In some rooms, the results were wrong at high frequencies, so we collected data from all the devices.","keys":["wrong","collected data","frequencies"]},{"ai":"And what was the cause?","aiTr":"Peki sebebi neydi?","hint":"The noise from old air conditioners was too loud at exactly those frequencies.","keys":["noise","air conditioners","loud"]},{"ai":"How did you solve it?","aiTr":"Nasıl çözdünüz?","hint":"We added a noise check. If the room is too noisy, the device warns the user.","keys":["noise check","warns","added"]},{"ai":"Have you had any problems since then?","aiTr":"O zamandan beri herhangi bir sorun yaşadınız mı?","hint":"No, we haven't. Since the update, the results have been correct in every clinic.","keys":["haven't","correct","since the update"]}]}},"te-04":{"intro":"Bulut mu, cihaz üzerinde mi? Teknik bir tartışmayı yönetip karar veriyorsun.","text":[{"who":"Engineer","en":"We need to decide where the AI runs: on the device or in the cloud.","tr":"Yapay zekânın nerede çalışacağına karar vermemiz gerekiyor: cihazda mı, bulutta mı?"},{"who":"Me","en":"What are the advantages of the cloud?","tr":"Bulutun avantajları neler?"},{"who":"Engineer","en":"The cloud is more powerful, and we can update the model easily.","tr":"Bulut daha güçlü ve modeli kolayca güncelleyebiliriz."},{"who":"Engineer","en":"However, it needs an internet connection, and some hospitals don't allow patient data to leave the building.","tr":"Ancak internet bağlantısı gerektiriyor ve bazı hastaneler hasta verisinin binadan çıkmasına izin vermiyor."},{"who":"Me","en":"And what happens if we run it on the device?","tr":"Peki onu cihazda çalıştırırsak ne olur?"},{"who":"Engineer","en":"The data will stay private and the test will work offline, but the hardware will be more expensive.","tr":"Veri gizli kalır ve test çevrimdışı çalışır, ama donanım daha pahalı olur."},{"who":"Me","en":"I've spoken to several hospitals, and every one of them has asked about privacy.","tr":"Birçok hastaneyle konuştum ve hepsi gizliliği sordu."},{"who":"Me","en":"Privacy is very important to our customers, so I think we should run the AI on the device.","tr":"Gizlilik müşterilerimiz için çok önemli, bu yüzden bence yapay zekâyı cihazda çalıştırmalıyız."},{"who":"Me","en":"We can still send updates once a month when the device is connected.","tr":"Cihaz bağlandığında yine de ayda bir güncelleme gönderebiliriz."},{"who":"Engineer","en":"That makes sense — it's a trade-off, but in this case privacy wins.","tr":"Mantıklı — bu bir ödünleşim, ama bu durumda gizlilik kazanıyor."}],"vocab":[{"en":"run on the device","tr":"cihazda çalışmak","ex":"The AI runs on the device.","def":"to work on a particular machine, not on the internet"},{"en":"the cloud","tr":"bulut","ex":"The cloud is more powerful.","def":"computers on the internet that store data and run software"},{"en":"advantage","tr":"avantaj","ex":"What are the advantages of the cloud?","def":"something that makes one option better"},{"en":"internet connection","tr":"internet bağlantısı","ex":"It needs an internet connection.","def":"a link to the internet"},{"en":"allow","tr":"izin vermek","ex":"Some hospitals don't allow patient data to leave the building.","def":"to let someone do something"},{"en":"work offline","tr":"çevrimdışı çalışmak","ex":"The test works offline.","def":"to work without the internet"},{"en":"trade-off","tr":"ödünleşim (bir şeyi kazanmak için başka bir şeyden vazgeçmek)","ex":"It's a trade-off, but privacy wins.","def":"a balance between two good things you can't fully have at the same time"},{"en":"That makes sense.","tr":"Mantıklı.","ex":"That makes sense, so let's do it.","def":"used to say you understand and agree"}],"grammar":{"title":"Should for recommendations","tr":"Bir öneri ya da tavsiye sunarken 'should + fiil' kullanılır. 'I think we should...' kibar ama net bir öneridir.","examples":["I think we should run the AI on the device.","We should send updates once a month.","Should we use the cloud?"]},"questions":[{"q":"What is an advantage of the cloud?","options":["It works offline","It is more powerful and easy to update","It is cheaper for hospitals"],"a":1},{"q":"Why do some hospitals not like the cloud?","options":["Patient data must not leave the building","It is too slow","It is too expensive"],"a":0},{"q":"What is the disadvantage of running the AI on the device?","options":["No privacy","No results offline","More expensive hardware"],"a":2},{"q":"What has every hospital asked about?","options":["Privacy","Price","Design"],"a":0}],"gaps":[{"s":"However, it needs an internet ___.","a":"connection","hint":"bağlantı"},{"s":"I think we ___ run the AI on the device.","a":"should","hint":"-meli / -malı"},{"s":"It's a ___, but in this case privacy wins.","a":"trade-off","hint":"ödünleşim"}],"order":[{"a":"The data will stay private and the test will work offline."},{"a":"I think we should run the AI on the device."}],"translate":[{"tr":"Avantajları neler?","en":"What are the advantages?","keys":["advantages"]},{"tr":"Bence yapay zekâyı cihazda çalıştırmalıyız.","en":"I think we should run the AI on the device.","keys":["should","on the device"]}],"roleplay":{"persona":"Hospital IT manager","personaTr":"Hastane bilgi işlem müdürü","scene":"Bir hastanenin bilgi işlem müdürü hasta verisinin nereye gittiğini ve neden bu çözümü seçtiğinizi soruyor.","turns":[{"ai":"Does your device send patient data to the internet?","aiTr":"Cihazınız hasta verisini internete gönderiyor mu?","hint":"No. The AI runs on the device, so the data stays private and the test works offline.","keys":["on the device","private","offline"]},{"ai":"Why didn't you use the cloud? It's more powerful.","aiTr":"Neden bulutu kullanmadınız? Daha güçlü.","hint":"That's true, but privacy is very important for hospitals. It's a trade-off, and privacy wins.","keys":["privacy","trade-off","important"]},{"ai":"Isn't the hardware more expensive?","aiTr":"Donanım daha pahalı değil mi?","hint":"Yes, it is, but every hospital we've spoken to has asked about privacy.","keys":["every hospital","privacy","spoken to"]},{"ai":"How do you update the software, then?","aiTr":"Peki yazılımı nasıl güncelliyorsunuz?","hint":"We send updates once a month when the device is connected.","keys":["once a month","updates","connected"]}]}},"sc-01":{"intro":"Hipotez, yöntem, katılımcılar ve sonuç: bir çalışmayı basit ama doğru terimlerle anlatmak.","text":[{"en":"To get certification, we needed to prove that our device gives the same results as a trained audiologist.","tr":"Sertifika almak için cihazımızın eğitimli bir odyologla aynı sonuçları verdiğini kanıtlamamız gerekiyordu."},{"en":"That's why we designed a clinical study with two university hospitals.","tr":"Bu yüzden iki üniversite hastanesiyle bir klinik çalışma tasarladık."},{"en":"Our hypothesis was simple: the device and the audiologist would agree in at least 90 percent of patients.","tr":"Hipotezimiz basitti: cihaz ve odyolog hastaların en az yüzde 90'ında aynı sonuca varacaktı."},{"en":"We recruited 200 participants between the ages of 18 and 75.","tr":"18 ile 75 yaş arasında 200 katılımcı topladık."},{"en":"Each participant had two tests on the same day: one with our device and one with an audiologist.","tr":"Her katılımcı aynı gün iki test yaptı: biri cihazımızla, biri bir odyologla."},{"en":"The audiologist never saw our device's results, so it was a blind comparison.","tr":"Odyolog cihazımızın sonuçlarını hiç görmedi, yani bu bir kör karşılaştırmaydı."},{"en":"In the end, the results matched in 94 percent of cases.","tr":"Sonunda sonuçlar vakaların yüzde 94'ünde eşleşti."},{"en":"In the other 6 percent, the difference was small and didn't change the diagnosis.","tr":"Kalan yüzde 6'da fark küçüktü ve teşhisi değiştirmedi."},{"en":"We published the results in a medical journal last spring.","tr":"Sonuçları geçen bahar bir tıp dergisinde yayımladık."},{"en":"The study has become one of the most important parts of our certification file.","tr":"Çalışma, sertifikasyon dosyamızın en önemli parçalarından biri haline geldi."}],"vocab":[{"en":"certification","tr":"sertifikasyon, belgelendirme","ex":"To get certification, we needed a clinical study.","def":"official approval that a product meets the rules"},{"en":"clinical study","tr":"klinik çalışma","ex":"We designed a clinical study with two hospitals.","def":"a scientific test of a medical product with real patients"},{"en":"hypothesis","tr":"hipotez","ex":"Our hypothesis was simple.","def":"an idea that you test in a study to see if it is true"},{"en":"recruit participants","tr":"katılımcı toplamak","ex":"We recruited 200 participants.","def":"to find people who agree to take part in a study"},{"en":"blind comparison","tr":"kör karşılaştırma","ex":"The audiologist didn't see our results, so it was a blind comparison.","def":"a comparison where the tester does not know the other result"},{"en":"match","tr":"eşleşmek, uyuşmak","ex":"The results matched in 94 percent of cases.","def":"to be the same as something else"},{"en":"diagnosis","tr":"teşhis","ex":"The difference didn't change the diagnosis.","def":"what a doctor decides is the patient's medical problem"},{"en":"publish","tr":"yayımlamak","ex":"We published the results in a medical journal.","def":"to make something available for people to read"}],"grammar":{"title":"Present perfect vs past simple","tr":"Geçmişte belirli bir zamanda bitmiş olaylar için past simple kullanılır (last spring). Zamanı belirtilmeyen ve sonucu bugün de önemli olan olaylar için present perfect kullanılır (has become).","examples":["We published the results last spring.","The study has become an important part of our file.","We recruited 200 participants."]},"questions":[{"q":"Why did they need the study?","options":["For a marketing campaign","To prove the device gives the same results as an audiologist","To find new investors"],"a":1},{"q":"What was the hypothesis?","options":["The results would match in at least 90 percent of patients","The device would be faster","The device would be cheaper"],"a":0},{"q":"What does \"blind comparison\" mean here?","options":["The patients could not see","The test was done in the dark","The audiologist did not see the device's results"],"a":2},{"q":"What happened in the other 6 percent of cases?","options":["The device failed completely","There was a small difference that didn't change the diagnosis","The patients left the study"],"a":1}],"gaps":[{"s":"Our ___ was simple.","a":"hypothesis","hint":"hipotez"},{"s":"We ___ 200 participants between the ages of 18 and 75.","a":"recruited","hint":"topladık"},{"s":"The difference didn't change the ___.","a":"diagnosis","hint":"teşhis"}],"order":[{"a":"The results matched in 94 percent of cases."},{"a":"We published the results in a medical journal last spring."}],"translate":[{"tr":"Her katılımcı aynı gün iki test yaptı.","en":"Each participant had two tests on the same day.","keys":["participant","two tests","same day"]},{"tr":"Fark küçüktü ve teşhisi değiştirmedi.","en":"The difference was small and didn't change the diagnosis.","keys":["difference","diagnosis"]}],"roleplay":{"persona":"University researcher","personaTr":"Üniversite araştırmacısı","scene":"Bir araştırmacı çalışmanızın hipotezini, yöntemini ve sonuçlarını soruyor.","turns":[{"ai":"Tell me about your clinical study. What was the hypothesis?","aiTr":"Klinik çalışmanızı anlatın. Hipotez neydi?","hint":"Our hypothesis was that the device and the audiologist would agree in at least 90 percent of patients.","keys":["hypothesis","90 percent","agree"]},{"ai":"How many participants did you have, and what was the method?","aiTr":"Kaç katılımcınız vardı ve yöntem neydi?","hint":"We recruited 200 participants. Each one had two tests on the same day, and it was a blind comparison.","keys":["recruited","200","blind comparison","same day"]},{"ai":"And what were the results?","aiTr":"Peki sonuçlar neydi?","hint":"The results matched in 94 percent of cases, and we published them in a medical journal last spring.","keys":["matched","94 percent","published"]},{"ai":"What about the other 6 percent?","aiTr":"Peki ya kalan yüzde 6?","hint":"The difference was small, and it didn't change the diagnosis.","keys":["small","diagnosis"]}]}},"te-02":{"intro":"Ekibin yapay zekâ araçlarıyla nasıl daha hızlı kod yazdığını ve neden dikkatli olduğunu anlatıyorsun.","text":[{"en":"Two years ago, our team wrote every line of code by hand.","tr":"İki yıl önce ekibimiz her kod satırını elle yazıyordu."},{"en":"Since then, AI coding assistants have become a big part of how we work.","tr":"O zamandan beri yapay zekâ kod asistanları çalışma şeklimizin büyük bir parçası haline geldi."},{"en":"An assistant can write code, explain code that someone else wrote and find bugs.","tr":"Bir asistan kod yazabilir, başkasının yazdığı kodu açıklayabilir ve hataları bulabilir."},{"en":"We describe what we want in plain English, and the assistant writes a first version.","tr":"Ne istediğimizi sade bir İngilizceyle anlatıyoruz ve asistan ilk sürümü yazıyor."},{"en":"Then our engineers review the code and test it carefully.","tr":"Sonra mühendislerimiz kodu inceleyip dikkatle test ediyor."},{"en":"This saves a lot of time: a task that used to take a week now takes a day or two.","tr":"Bu çok zaman kazandırıyor: Eskiden bir hafta süren bir iş artık bir iki gün sürüyor."},{"en":"However, AI can write code that looks correct but has hidden problems.","tr":"Ancak yapay zekâ doğru görünen ama gizli sorunları olan kod yazabilir."},{"en":"Our software runs on a medical device, so we can't take any risks.","tr":"Yazılımımız bir tıbbi cihazda çalışıyor, bu yüzden hiçbir risk alamayız."},{"en":"That's why we never deploy code without a human review and automatic tests.","tr":"Bu yüzden insan incelemesi ve otomatik testler olmadan asla kodu canlıya almıyoruz."},{"en":"For a small startup with only three engineers, these tools are like having three extra engineers.","tr":"Yalnızca üç mühendisi olan küçük bir girişim için bu araçlar, üç ekstra mühendis gibi."}],"vocab":[{"en":"coding assistant","tr":"kod asistanı","ex":"AI coding assistants have become a big part of our work.","def":"an AI tool that helps people write and understand code"},{"en":"find bugs","tr":"hata bulmak","ex":"The assistant can find bugs quickly.","def":"to discover mistakes in computer code"},{"en":"plain English","tr":"sade İngilizce","ex":"We describe the task in plain English.","def":"simple, clear language without technical words"},{"en":"review the code","tr":"kodu incelemek","ex":"Our engineers review the code before it goes live.","def":"to read code carefully to check that it is correct"},{"en":"save time","tr":"zaman kazandırmak","ex":"AI tools save us a lot of time.","def":"to make something take less time"},{"en":"hidden problem","tr":"gizli sorun","ex":"The code looked correct but had a hidden problem.","def":"a problem that is not easy to see"},{"en":"deploy","tr":"canlıya almak, yayınlamak","ex":"We never deploy code without tests.","def":"to put new software into use for real users"},{"en":"take a risk","tr":"risk almak","ex":"With a medical device, we can't take any risks.","def":"to do something that could have a bad result"}],"grammar":{"title":"Linking words: however, so, that's why","tr":"'However' zıtlık bildirir (ancak). 'So' ve 'that's why' sonuç bildirir (bu yüzden). Cümleleri birbirine bağlayarak anlatımı daha akıcı yapar.","examples":["However, AI can write code that looks correct but has hidden problems.","Our software runs on a medical device, so we can't take any risks.","That's why we never deploy code without a human review."]},"questions":[{"q":"What has changed in the last two years?","options":["The team has hired more engineers","AI coding assistants have become a big part of their work","They have stopped testing"],"a":1},{"q":"What happens after the assistant writes the first version?","options":["The engineers review and test it","It goes straight to customers","The investors check it"],"a":0},{"q":"Why can't the team take any risks?","options":["Their engineers are new","They have no money","Their software runs on a medical device"],"a":2},{"q":"How do the tools help a small startup?","options":["They replace all the engineers","They make the device cheaper","They find new customers","They're like having extra engineers"],"a":3}],"gaps":[{"s":"We describe what we want in ___ English.","a":"plain","hint":"sade"},{"s":"Our engineers ___ the code and test it carefully.","a":"review","hint":"incelemek"},{"s":"We never ___ code without a human review and automatic tests.","a":"deploy","hint":"canlıya almak"}],"order":[{"a":"An assistant can write code and find bugs."},{"a":"This saves a lot of time."}],"translate":[{"tr":"Bu çok zaman kazandırıyor.","en":"This saves a lot of time.","keys":["saves","a lot of time"]},{"tr":"Yapay zekâ kod asistanları işimizin büyük bir parçası haline geldi.","en":"AI coding assistants have become a big part of our work.","keys":["have become","big part"]}],"roleplay":{"persona":"Tech investor","personaTr":"Teknoloji yatırımcısı","scene":"Bir yatırımcı küçük ekibinizin nasıl bu kadar hızlı ürün çıkardığını ve bunun güvenli olup olmadığını soruyor.","turns":[{"ai":"Your team is very small. How do you build software so fast?","aiTr":"Ekibiniz çok küçük. Yazılımı nasıl bu kadar hızlı geliştiriyorsunuz?","hint":"We use AI coding assistants. We describe what we want in plain English, and the assistant writes a first version.","keys":["coding assistants","plain English","first version"]},{"ai":"Is AI code safe? Can you trust it?","aiTr":"Yapay zekânın yazdığı kod güvenli mi? Ona güvenebilir misiniz?","hint":"Not always. It can look correct but have hidden problems, so our engineers review it and we run automatic tests.","keys":["hidden problems","review","tests"]},{"ai":"Why are you so careful?","aiTr":"Neden bu kadar dikkatlisiniz?","hint":"Because our software runs on a medical device, so we can't take any risks.","keys":["medical device","risks"]},{"ai":"How much time does it really save?","aiTr":"Gerçekte ne kadar zaman kazandırıyor?","hint":"A lot. A task that used to take a week now takes a day or two.","keys":["used to take a week","a day or two","a lot"]}]}},"sc-02":{"intro":"Hibe programları, başvuru süreci ve hibe ile yatırım arasındaki fark.","text":[{"en":"Not all the money for a startup comes from investors; some of it comes from grants.","tr":"Bir girişimin parasının hepsi yatırımcılardan gelmez; bir kısmı hibelerden gelir."},{"en":"A grant is money that you don't have to pay back, and you don't have to give away any equity.","tr":"Hibe, geri ödemek zorunda olmadığınız paradır ve karşılığında hisse vermeniz de gerekmez."},{"en":"Last year, we applied for a European innovation grant for health technology.","tr":"Geçen yıl sağlık teknolojisi için bir Avrupa inovasyon hibesine başvurduk."},{"en":"The application was long, and we had to describe the problem, our solution, the team and the budget.","tr":"Başvuru uzundu; sorunu, çözümümüzü, ekibi ve bütçeyi anlatmak zorundaydık."},{"en":"We also had to explain the impact: how many people will benefit from our device?","tr":"Etkiyi de açıklamamız gerekiyordu: cihazımızdan kaç kişi fayda görecek?"},{"en":"After a four-month review, we were invited to an interview with a jury.","tr":"Dört aylık bir değerlendirmenin ardından bir jüriyle mülakata davet edildik."},{"en":"In the end, we won 250,000 euros, which we can only use for research and clinical validation.","tr":"Sonunda 250.000 euro kazandık; bu parayı yalnızca araştırma ve klinik doğrulama için kullanabiliyoruz."},{"en":"Since then, the grant has paid for a large part of our research.","tr":"O zamandan beri hibe, araştırmamızın büyük bir kısmını karşıladı."},{"en":"Grants take a lot of time; however, they are a great way to fund early research.","tr":"Hibeler çok zaman alır; ancak erken aşama araştırmayı finanse etmenin harika bir yoludur."}],"vocab":[{"en":"pay back","tr":"geri ödemek","ex":"You don't have to pay back a grant.","def":"to return money that you borrowed"},{"en":"give away equity","tr":"hisse vermek","ex":"With a grant, you don't give away any equity.","def":"to give part of the ownership of your company to someone"},{"en":"apply for","tr":"...e başvurmak","ex":"We applied for a European innovation grant.","def":"to formally ask for something, usually in writing"},{"en":"budget","tr":"bütçe","ex":"We had to describe the budget.","def":"a plan of how much money you will spend and on what"},{"en":"impact","tr":"etki","ex":"We had to explain the impact of our device.","def":"the effect that something has on people or a situation"},{"en":"benefit from","tr":"...den fayda görmek","ex":"Millions of people can benefit from the device.","def":"to get something good or useful from something"},{"en":"be invited to","tr":"...e davet edilmek","ex":"We were invited to an interview with a jury.","def":"to be asked to come to an event or meeting"},{"en":"fund","tr":"finanse etmek","ex":"Grants are a great way to fund early research.","def":"to provide money for something"}],"grammar":{"title":"have to / don't have to","tr":"'have to' bir zorunluluğu anlatır (we had to describe). 'don't have to' ise yasak değil, gereklilik olmadığını anlatır: yapmana gerek yok.","examples":["We had to describe the budget.","You don't have to pay back a grant.","You don't have to give away any equity."]},"questions":[{"q":"How is a grant different from an investment?","options":["You don't pay it back or give equity","A grant is always bigger","A grant comes from customers"],"a":0},{"q":"What did they have to explain about the impact?","options":["How much the office costs","How many people will benefit from the device","Who their competitors are"],"a":1},{"q":"What happened after the review?","options":["They got the money immediately","They had to apply again","They were invited to an interview with a jury"],"a":2},{"q":"What can the money be used for?","options":["Marketing","Research and clinical validation","Founders' salaries"],"a":1}],"gaps":[{"s":"A grant is money that you don't have to pay ___.","a":"back","hint":"geri"},{"s":"How many people will ___ from our device?","a":"benefit","hint":"fayda görmek"},{"s":"We ___ to an interview with a jury.","a":"were invited","hint":"davet edildik"}],"order":[{"a":"We were invited to an interview with a jury."},{"a":"Last year we applied for a European innovation grant."}],"translate":[{"tr":"Hibeler çok zaman alır.","en":"Grants take a lot of time.","keys":["grants","a lot of time"]},{"tr":"Hisse vermek zorunda değilsiniz.","en":"You don't have to give away any equity.","keys":["don't have to","equity"]}],"roleplay":{"persona":"Grant jury member","personaTr":"Hibe jürisi üyesi","scene":"Hibe mülakatındasın. Jüri etkiyi, bütçeyi ve ekibi soruyor.","turns":[{"ai":"Thank you for your application. What impact will your project have?","aiTr":"Başvurunuz için teşekkürler. Projenizin nasıl bir etkisi olacak?","hint":"One in five people has some hearing loss, and in small towns people wait months for a test. Our device can help millions of them.","keys":["one in five","small towns","help"]},{"ai":"How will you use the grant money?","aiTr":"Hibe parasını nasıl kullanacaksınız?","hint":"We'll use the budget for research and clinical validation, for example a clinical study with two university hospitals.","keys":["budget","research","clinical validation"]},{"ai":"Why should we fund your team and not another one?","aiTr":"Neden başka bir ekibi değil de sizi finanse edelim?","hint":"We already have a working prototype, and our team has three engineers, a doctor and two business people.","keys":["prototype","engineers","doctor"]}]}},"ai-04":{"intro":"CE işareti, FDA, risk sınıfı ve klinik doğrulama gibi kavramları bir yatırımcıya açıklıyorsun.","text":[{"en":"In Europe, a medical device cannot be sold without the CE mark.","tr":"Avrupa'da tıbbi bir cihaz CE işareti olmadan satılamaz."},{"en":"In the United States, we will also need FDA approval later.","tr":"Amerika Birleşik Devletleri'nde ise ileride FDA onayına da ihtiyacımız olacak."},{"en":"Our audiometer is a Class IIa device, which means it has a medium level of risk.","tr":"Odyometremiz Sınıf IIa bir cihaz, yani orta düzeyde bir riske sahip."},{"en":"To get the CE mark, we have to prove that the device is safe and works as we say.","tr":"CE işaretini almak için cihazın güvenli olduğunu ve söylediğimiz gibi çalıştığını kanıtlamak zorundayız."},{"en":"This is called clinical validation.","tr":"Buna klinik doğrulama denir."},{"en":"We have already compared our results with those of trained audiologists in two university hospitals.","tr":"Sonuçlarımızı iki üniversite hastanesinde eğitimli odyologların sonuçlarıyla zaten karşılaştırdık."},{"en":"The results matched in 94% of cases, and the study was published last spring.","tr":"Sonuçlar vakaların %94'ünde eşleşti ve çalışma geçen bahar yayımlandı."},{"en":"We also have to build a quality management system and prepare a lot of documentation.","tr":"Ayrıca bir kalite yönetim sistemi kurmamız ve çok fazla dokümantasyon hazırlamamız gerekiyor."},{"en":"The process is slow and expensive, but in the end it protects patients, and it protects us too.","tr":"Süreç yavaş ve pahalı ama sonuçta hastaları koruyor, bizi de koruyor."},{"en":"If everything goes to plan, we will complete certification by the end of next year.","tr":"Her şey plana göre giderse sertifikasyonu gelecek yılın sonuna kadar tamamlayacağız."}],"vocab":[{"en":"certification","tr":"sertifikasyon, belgelendirme","ex":"We need certification before we can sell the device in Europe.","def":"official proof that a product meets the required standards"},{"en":"FDA approval","tr":"FDA onayı","ex":"We will apply for FDA approval later.","def":"permission from the US authority to sell a medical product"},{"en":"prove","tr":"kanıtlamak","ex":"We have to prove that the device is safe.","def":"to show with facts that something is true"},{"en":"clinical validation","tr":"klinik doğrulama","ex":"Clinical validation shows that the device works with real patients.","def":"testing a medical product with real patients to show that it works"},{"en":"compare with","tr":"...ile karşılaştırmak","ex":"We compared our results with those of trained audiologists.","def":"to look at two things to see how similar they are"},{"en":"quality management system","tr":"kalite yönetim sistemi","ex":"A quality management system controls how we design and build the device.","def":"a set of rules and processes that make sure a product is always made well"},{"en":"documentation","tr":"dokümantasyon, belgeler","ex":"Certification needs a lot of documentation.","def":"written records that explain and prove how something works"},{"en":"go to plan","tr":"plana göre gitmek","ex":"If everything goes to plan, we will finish next year.","def":"to happen in the way you expected"}],"grammar":{"title":"Present perfect vs past simple","tr":"Present perfect (have + V3) geçmişte olmuş ama şimdi önemli olan şeyler için kullanılır; zamanı söylemeyiz. Zaman belliyse (last spring) past simple kullanırız.","examples":["We have already compared our results with trained audiologists.","The study was published last spring.","Have you started the certification process?"]},"questions":[{"q":"What does the company need to sell the device in Europe?","options":["FDA approval","A patent","The CE mark","A distributor"],"a":2},{"q":"What does 'Class IIa' tell us about the device?","options":["It has a medium level of risk","It is very cheap","It is only for children"],"a":0},{"q":"What is clinical validation?","options":["Selling the device to clinics","Proving that the device is safe and works","Training doctors to use the device"],"a":1},{"q":"When will they complete certification if everything goes to plan?","options":["By the end of this year","In five years","Next month","By the end of next year"],"a":3}],"gaps":[{"s":"To get the CE mark, we have to ___ that the device is safe.","a":"prove","hint":"kanıtlamak"},{"s":"This is called clinical ___.","a":"validation","hint":"doğrulama"},{"s":"If everything goes to ___, we will finish by the end of next year.","a":"plan","hint":"plan"}],"order":[{"a":"The process is slow and expensive."},{"a":"We also have to build a quality management system."}],"translate":[{"tr":"Sonuçlarımızı eğitimli odyologlarınkiyle karşılaştırdık.","en":"We have compared our results with those of trained audiologists.","keys":["compared","results","audiologists"]},{"tr":"Her şey plana göre giderse gelecek yılın sonuna kadar bitireceğiz.","en":"If everything goes to plan, we will finish by the end of next year.","keys":["goes to plan","end of next year"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı (mevzuat soruları)","scene":"Yatırımcı sertifikasyon riskini ve zaman planını soruyor.","turns":[{"ai":"Can you sell the device in Europe today?","aiTr":"Cihazı bugün Avrupa'da satabilir misiniz?","hint":"Not yet. In Europe, a medical device cannot be sold without the CE mark.","keys":["CE mark","not yet","cannot be sold","certification"]},{"ai":"What do you have to do to get the CE mark?","aiTr":"CE işaretini almak için ne yapmanız gerekiyor?","hint":"We have to prove that the device is safe and works. This is called clinical validation.","keys":["prove","safe","clinical validation"]},{"ai":"Have you already tested it with patients?","aiTr":"Cihazı hastalarla test ettiniz mi?","hint":"Yes. We have compared our results with trained audiologists in two university hospitals, and they matched in 94% of cases.","keys":["94","compared","two university hospitals","matched"]},{"ai":"When will you finish?","aiTr":"Ne zaman bitireceksiniz?","hint":"If everything goes to plan, we will complete certification by the end of next year.","keys":["end of next year","goes to plan","complete"]}]}},"st-03":{"intro":"İki seçenek arasında nasıl karar verdiğinizi, artıları ve eksileri tartarak anlatıyorsun.","text":[{"en":"Last month, we had to make one of the most difficult decisions since we started the company.","tr":"Geçen ay, şirketi kurduğumuzdan beri verdiğimiz en zor kararlardan birini vermek zorunda kaldık."},{"en":"We had two options: sell our device directly to hospitals, or work with a distributor who already knows the market.","tr":"İki seçeneğimiz vardı: cihazımızı doğrudan hastanelere satmak ya da pazarı zaten bilen bir distribütörle çalışmak."},{"en":"Selling directly means higher profit, but it takes a lot of time and a big sales team.","tr":"Doğrudan satmak daha yüksek kâr demek ama çok zaman ve büyük bir satış ekibi gerektiriyor."},{"en":"A distributor takes a percentage of every sale; however, they can reach many customers quickly.","tr":"Distribütör her satıştan bir yüzde alıyor; ancak birçok müşteriye hızla ulaşabiliyor."},{"en":"We discussed the pros and cons for two weeks, and the whole team gave their opinion.","tr":"İki hafta boyunca artıları ve eksileri tartıştık ve tüm ekip fikrini söyledi."},{"en":"Our engineers wanted to focus on the product, not on sales calls.","tr":"Mühendislerimiz satış görüşmelerine değil, ürüne odaklanmak istiyordu."},{"en":"In the end, we decided to go with the distributor.","tr":"Sonunda distribütörle ilerlemeye karar verdik."},{"en":"The main reason was speed, because for a startup, time is the most important resource.","tr":"Ana sebep hızdı, çünkü bir girişim için zaman en önemli kaynaktır."},{"en":"If we wait too long, a bigger company might enter the market before us.","tr":"Çok beklersek daha büyük bir şirket pazara bizden önce girebilir."},{"en":"It wasn't an easy choice, but I still think it was the right one.","tr":"Kolay bir seçim değildi ama hâlâ doğru olduğunu düşünüyorum."}],"vocab":[{"en":"make a decision","tr":"karar vermek","ex":"We had to make a difficult decision.","def":"to choose something after thinking about it"},{"en":"directly","tr":"doğrudan","ex":"We could sell our device directly to hospitals.","def":"without another company in the middle"},{"en":"distributor","tr":"distribütör, dağıtıcı","ex":"A distributor already knows the market.","def":"a company that buys and sells another company's products"},{"en":"take a percentage","tr":"yüzde almak, pay almak","ex":"A distributor takes a percentage of every sale.","def":"to keep part of the money from each sale"},{"en":"pros and cons","tr":"artılar ve eksiler","ex":"We discussed the pros and cons for two weeks.","def":"the advantages and disadvantages of something"},{"en":"go with","tr":"...i seçmek, ...le ilerlemek","ex":"We decided to go with the distributor.","def":"to choose one option"},{"en":"in the end","tr":"sonunda","ex":"In the end, we chose the distributor.","def":"finally, after a long time or discussion"},{"en":"resource","tr":"kaynak","ex":"Time is our most important resource.","def":"something useful that you have, like money, people or time"}],"grammar":{"title":"Linking words: however / in the end","tr":"'However' iki fikir arasında zıtlık kurar ve genelde noktalı virgül ya da noktadan sonra gelir. 'In the end' uzun bir süreçten sonra varılan sonucu anlatır.","examples":["A distributor takes a percentage; however, they can reach many customers quickly.","In the end, we decided to go with the distributor."]},"questions":[{"q":"What were the two options?","options":["Hire more engineers or build a new device","Sell directly or work with a distributor","Raise money or close the company"],"a":1},{"q":"What is the main disadvantage of selling directly?","options":["It takes a lot of time","It gives lower profit","Hospitals don't like it"],"a":0},{"q":"What did the engineers want?","options":["Higher salaries","More sales calls","To focus on the product"],"a":2},{"q":"What could happen if they wait too long?","options":["The device might stop working","A bigger company might enter the market first","The distributor might lower its percentage"],"a":1}],"gaps":[{"s":"We discussed the pros and ___ for two weeks.","a":"cons","hint":"eksiler"},{"s":"For a startup, time is the most important ___.","a":"resource","hint":"kaynak"},{"s":"In the end, we decided to ___ with the distributor.","a":"go","hint":"ilerlemek, seçmek"}],"order":[{"a":"In the end we decided to go with the distributor."},{"a":"Time is our most important resource."}],"translate":[{"tr":"Kolay bir seçim değildi ama bence doğru olandı.","en":"It wasn't an easy choice, but I think it was the right one.","keys":["easy choice","right one"]},{"tr":"Çok beklersek daha büyük bir şirket pazara bizden önce girebilir.","en":"If we wait too long, a bigger company might enter the market first.","keys":["wait too long","enter the market"]}],"roleplay":{"persona":"Co-founder","personaTr":"Kurucu ortak","scene":"Kurucu ortağın, distribütör mü yoksa doğrudan satış mı sorusunu seninle bir kez daha tartışmak istiyor.","turns":[{"ai":"I think we should sell directly to hospitals. What do you think?","aiTr":"Bence doğrudan hastanelere satmalıyız. Sen ne düşünüyorsun?","hint":"Selling directly means higher profit, but it takes a lot of time and a big sales team.","keys":["profit","time","sales team"]},{"ai":"OK, but a distributor takes a percentage of every sale. Isn't that a problem?","aiTr":"Tamam ama distribütör her satıştan yüzde alıyor. Bu bir sorun değil mi?","hint":"Yes, they take a percentage; however, they can reach many customers quickly.","keys":["however","quickly","reach"]},{"ai":"What if we just wait a few more months and decide later?","aiTr":"Birkaç ay daha bekleyip sonra karar versek?","hint":"If we wait too long, a bigger company might enter the market before us.","keys":["wait too long","bigger company","market"]},{"ai":"So what's your final decision?","aiTr":"Peki son kararın ne?","hint":"In the end, I think we should go with the distributor, and the main reason is speed.","keys":["go with","distributor","speed"]}]}},"li-01":{"intro":"İş seyahatinde pasaport kontrolünden geçiyor, otele giriş yapıyor ve kibar ricalarda bulunuyorsun.","text":[{"who":"Officer","en":"Good morning, what's the purpose of your visit?","tr":"Günaydın, ziyaretinizin amacı nedir?"},{"who":"Me","en":"I'm here on business: I'm attending a medical technology conference.","tr":"İş için buradayım: bir medikal teknoloji konferansına katılıyorum."},{"who":"Officer","en":"How long are you planning to stay?","tr":"Ne kadar kalmayı planlıyorsunuz?"},{"who":"Me","en":"Four days, and I've already booked my flight back on Friday.","tr":"Dört gün; cuma günkü dönüş uçuşumu da zaten ayırttım."},{"who":"Officer","en":"That's fine, enjoy your stay.","tr":"Tamamdır, iyi konaklamalar."},{"who":"Me","en":"Hi, I've got a reservation under the name {name}.","tr":"Merhaba, {name} adına bir rezervasyonum var."},{"who":"Receptionist","en":"Welcome to the hotel; could I see your passport, please?","tr":"Otelimize hoş geldiniz; pasaportunuzu görebilir miyim, lütfen?"},{"who":"Me","en":"Of course, here you are, and is breakfast included in the price?","tr":"Tabii, buyurun; kahvaltı fiyata dahil mi?"},{"who":"Receptionist","en":"Yes, breakfast is served from 7 to 10, and here's your key card for room 512 on the fifth floor.","tr":"Evet, kahvaltı 7'den 10'a kadar servis ediliyor; işte beşinci kattaki 512 numaralı odanızın anahtar kartı."},{"who":"Me","en":"Thanks, and could you tell me the wifi password, please?","tr":"Teşekkürler; wifi şifresini söyleyebilir misiniz, lütfen?"}],"vocab":[{"en":"purpose of your visit","tr":"ziyaretinizin amacı","ex":"What's the purpose of your visit?","def":"the reason why you are travelling to a place"},{"en":"on business","tr":"iş için","ex":"I'm here on business.","def":"travelling for work, not for a holiday"},{"en":"attend a conference","tr":"konferansa katılmak","ex":"I'm attending a medical technology conference.","def":"to go to and take part in a conference"},{"en":"book a flight","tr":"uçuş ayırtmak","ex":"I've already booked my flight back.","def":"to reserve a seat on a plane"},{"en":"reservation under the name","tr":"... adına rezervasyon","ex":"I've got a reservation under the name {name}.","def":"a booking that is saved with a person's name"},{"en":"included in the price","tr":"fiyata dahil","ex":"Is breakfast included in the price?","def":"part of what you pay, with no extra cost"},{"en":"key card","tr":"anahtar kart","ex":"Here's your key card for room 512.","def":"a plastic card that opens a hotel room door"},{"en":"Could you tell me...?","tr":"...söyleyebilir misiniz?","ex":"Could you tell me the wifi password?","def":"a polite way to ask for information"}],"grammar":{"title":"Polite requests: Could I...? / Could you...?","tr":"Kibar rica için 'Could I...?' (bir şey yapmak için izin) ve 'Could you...?' (birinden bir şey yapmasını rica) kullanılır. Sonuna 'please' eklemek daha da kibar yapar.","examples":["Could I see your passport, please?","Could you tell me the wifi password?","Could you order a taxi for me?"]},"questions":[{"q":"Why is the speaker visiting?","options":["On holiday","On business, for a conference","To study"],"a":1},{"q":"How long is the speaker planning to stay?","options":["Four days","A week","Two days"],"a":0},{"q":"What does the receptionist give the speaker?","options":["A map","A breakfast voucher","A key card for room 512"],"a":2},{"q":"What does the speaker ask at the end?","options":["The check-out time","The wifi password","The way to the conference"],"a":1}],"gaps":[{"s":"I'm here on ___.","a":"business","hint":"iş (için)"},{"s":"Is breakfast ___ in the price?","a":"included","hint":"dahil"},{"s":"Could you tell me the wifi ___, please?","a":"password","hint":"şifre"}],"order":[{"a":"How long are you planning to stay?"},{"a":"I've already booked my flight back on Friday."}],"translate":[{"tr":"Dönüş uçuşumu zaten ayırttım.","en":"I've already booked my flight back.","keys":["already booked","flight back"]},{"tr":"Kahvaltı fiyata dahil mi?","en":"Is breakfast included in the price?","keys":["breakfast","included in the price"]}],"roleplay":{"persona":"Hotel receptionist","personaTr":"Otel resepsiyonisti","scene":"Berlin'de otele akşam geç saatte giriş yapıyorsun ve ertesi gün için yardım istiyorsun.","turns":[{"ai":"Good evening and welcome! Do you have a booking with us?","aiTr":"İyi akşamlar, hoş geldiniz! Bizde rezervasyonunuz var mı?","hint":"Yes, I have a reservation under the name {name} for four days.","keys":["reservation","under the name","four days"]},{"ai":"Lovely. Could I see your passport, please?","aiTr":"Harika. Pasaportunuzu görebilir miyim, lütfen?","hint":"Of course, here you are. Is breakfast included in the price?","keys":["here you are","breakfast","included"]},{"ai":"Yes, from 7 to 10. Your room is 512, on the fifth floor. Is there anything else?","aiTr":"Evet, 7'den 10'a kadar. Odanız beşinci katta, 512. Başka bir şey var mı?","hint":"Could you tell me the wifi password, please? I have to work tonight.","keys":["could you tell me","wifi password","work"]},{"ai":"Sure, it's on this card. Do you need anything for tomorrow?","aiTr":"Tabii, bu kartta yazıyor. Yarın için bir şeye ihtiyacınız var mı?","hint":"Could you order a taxi to the conference centre for 8 o'clock?","keys":["taxi","order","conference"]}]}},"co-01":{"intro":"Bir konferansta yeni biriyle tanışıyor, girişimini ve ürününü kısa ve net biçimde anlatıyorsun.","text":[{"who":"Me","en":"Hi, I don't think we've met yet — I'm {name}.","tr":"Merhaba, sanırım henüz tanışmadık; ben {name}."},{"who":"Sarah","en":"Hi {name}, I'm Sarah, and I work for a hospital group in the UK.","tr":"Merhaba {name}, ben Sarah; İngiltere'de bir hastane grubunda çalışıyorum."},{"who":"Me","en":"Nice to meet you, Sarah — I'm the founder of AIHEAR, a medical device startup from Turkey.","tr":"Tanıştığımıza memnun oldum Sarah; ben Türkiye'den bir tıbbi cihaz girişimi olan AIHEAR'ın kurucusuyum."},{"who":"Sarah","en":"Oh, what kind of device have you developed?","tr":"Aa, ne tür bir cihaz geliştirdiniz?"},{"who":"Me","en":"We've built an audiometer that tests hearing on its own, so patients don't need an expert in the room.","tr":"İşitmeyi kendi kendine test eden bir odyometre geliştirdik, böylece hastaların odada bir uzmana ihtiyacı olmuyor."},{"who":"Me","en":"Basically, it works like a self-service hearing test and takes less than ten minutes.","tr":"Kısacası self servis bir işitme testi gibi çalışıyor ve on dakikadan kısa sürüyor."},{"who":"Sarah","en":"That sounds really useful, because our waiting lists for hearing tests have become very long.","tr":"Kulağa gerçekten faydalı geliyor, çünkü işitme testleri için bekleme listelerimiz çok uzadı."},{"who":"Me","en":"That's exactly the problem we're trying to solve, especially outside the big cities.","tr":"Çözmeye çalıştığımız sorun tam olarak bu, özellikle büyük şehirlerin dışında."},{"who":"Me","en":"Here's my card — should we talk more after the next session?","tr":"Buyurun kartım; bir sonraki oturumdan sonra daha fazla konuşalım mı?"},{"who":"Sarah","en":"Definitely, let's meet by the coffee stand after the next session.","tr":"Kesinlikle, bir sonraki oturumdan sonra kahve standının yanında buluşalım."}],"vocab":[{"en":"I don't think we've met","tr":"sanırım tanışmadık","ex":"Hi, I don't think we've met yet.","def":"a polite way to start talking to someone new"},{"en":"work for","tr":"...de çalışmak","ex":"Sarah works for a hospital group in the UK.","def":"to be employed by a company or organisation"},{"en":"founder of","tr":"...nın kurucusu","ex":"I'm the founder of AIHEAR.","def":"the person who started a company"},{"en":"develop a device","tr":"cihaz geliştirmek","ex":"What kind of device have you developed?","def":"to design and build a new product"},{"en":"on its own","tr":"kendi kendine","ex":"The audiometer tests hearing on its own.","def":"without help from anyone"},{"en":"self-service","tr":"self servis","ex":"It works like a self-service hearing test.","def":"done by the user without help from staff"},{"en":"waiting list","tr":"bekleme listesi","ex":"Our waiting lists have become very long.","def":"a list of people who are waiting for a service"},{"en":"solve a problem","tr":"bir sorunu çözmek","ex":"That's exactly the problem we're trying to solve.","def":"to find an answer to a difficulty"}],"grammar":{"title":"Present perfect: experience and results","tr":"Zamanı belirtilmeyen ve sonucu şimdi önemli olan olaylar için 'have/has + V3' kullanılır. Kendini tanıtırken ne yaptığını anlatmak için çok kullanışlıdır.","examples":["I don't think we've met yet.","We've built an audiometer that tests hearing on its own.","Our waiting lists have become very long."]},"questions":[{"q":"How long does the hearing test take?","options":["About an hour","A whole day","Less than ten minutes"],"a":2},{"q":"Why does Sarah think the device is useful?","options":["It is cheaper than a hearing aid","Her hospital group has long waiting lists","She needs a new job"],"a":1},{"q":"What does 'on its own' mean in the text?","options":["Without help from an expert","With a doctor in the room","Only at home"],"a":0},{"q":"What do they agree to do?","options":["Sign a contract today","Meet after the next session","Visit a hospital together"],"a":1}],"gaps":[{"s":"Oh, what kind of device have you ___?","a":"developed","hint":"geliştirmek"},{"s":"The audiometer tests hearing on its ___.","a":"own","hint":"kendi kendine"},{"s":"Our ___ lists for hearing tests have become very long.","a":"waiting","hint":"bekleme"}],"order":[{"a":"We have built an audiometer that tests hearing on its own."},{"a":"That is exactly the problem we are trying to solve."}],"translate":[{"tr":"Sanırım henüz tanışmadık.","en":"I don't think we've met yet.","keys":["don't think","met yet"]},{"tr":"Bir sonraki oturumdan sonra daha fazla konuşalım mı?","en":"Should we talk more after the next session?","keys":["should we","next session"]}],"roleplay":{"persona":"Conference attendee","personaTr":"Konferans katılımcısı","scene":"Kahve kuyruğunda İrlandalı bir klinik yöneticisi seninle konuşmaya başlıyor.","turns":[{"ai":"Hi there! I'm Emma, from a clinic chain in Ireland. I don't think we've met.","aiTr":"Merhaba! Ben Emma, İrlanda'daki bir klinik zincirindenim. Sanırım tanışmadık.","hint":"Nice to meet you, Emma. I'm {name}, the founder of AIHEAR, a medical device startup from Turkey.","keys":["nice to meet","founder","startup","Turkey"]},{"ai":"What kind of device have you developed?","aiTr":"Ne tür bir cihaz geliştirdiniz?","hint":"We've built an audiometer that tests hearing on its own, so patients don't need an expert in the room.","keys":["audiometer","on its own","expert"]},{"ai":"Interesting. Our waiting lists have become really long lately.","aiTr":"İlginç. Son zamanlarda bekleme listelerimiz gerçekten uzadı.","hint":"That's exactly the problem we're trying to solve. A test takes less than ten minutes.","keys":["exactly","problem","ten minutes"]},{"ai":"I'd love to hear more, but the next session is starting.","aiTr":"Daha fazlasını duymak isterdim ama bir sonraki oturum başlıyor.","hint":"Here's my card. Should we talk more after the session?","keys":["card","should we","after the session"]}]}},"st-01":{"intro":"Bir konferans arasında olası bir ortağa ürününü, müşterilerini ve ekibini anlatıyorsun.","text":[{"who":"Partner","en":"So, what exactly does your company do?","tr":"Peki, şirketiniz tam olarak ne yapıyor?"},{"who":"Me","en":"We're a medical technology startup from Turkey, and we've built a device that tests hearing automatically.","tr":"Türkiye'den bir medikal teknoloji girişimiyiz ve işitmeyi otomatik olarak test eden bir cihaz geliştirdik."},{"who":"Me","en":"The patient puts on headphones and presses a button when they hear a sound.","tr":"Hasta kulaklığı takıyor ve bir ses duyduğunda bir düğmeye basıyor."},{"who":"Me","en":"The test takes under ten minutes, and you don't need an expert in the room.","tr":"Test on dakikadan kısa sürüyor ve odada bir uzmana gerek yok."},{"who":"Partner","en":"That sounds useful, but who actually buys it?","tr":"Kulağa faydalı geliyor ama onu aslında kim satın alıyor?"},{"who":"Me","en":"Our customers are hospitals, clinics and hearing aid shops that don't have enough audiologists.","tr":"Müşterilerimiz yeterli odyoloğu olmayan hastaneler, klinikler ve işitme cihazı mağazaları."},{"who":"Me","en":"So far, we've signed five paying customers.","tr":"Şimdiye kadar beş ücretli müşteriyle anlaştık."},{"who":"Partner","en":"And how big is your team at the moment?","tr":"Peki ekibiniz şu an ne kadar büyük?"},{"who":"Me","en":"There are six of us: three engineers, one doctor and two business people.","tr":"Altı kişiyiz: üç mühendis, bir doktor ve iki iş insanı."},{"who":"Me","en":"Our next step is to find partners in Europe, which is why I'm here today.","tr":"Bir sonraki adımımız Avrupa'da ortaklar bulmak, bugün burada olmamın nedeni de bu."}],"vocab":[{"en":"build a device","tr":"bir cihaz geliştirmek","ex":"We've built a device that tests hearing.","def":"to design and make a machine or tool"},{"en":"automatically","tr":"otomatik olarak","ex":"The device tests hearing automatically.","def":"by itself, without a person controlling it"},{"en":"press a button","tr":"bir düğmeye basmak","ex":"The patient presses a button when they hear a sound.","def":"to push a button with your finger"},{"en":"take under ten minutes","tr":"on dakikadan kısa sürmek","ex":"The test takes under ten minutes.","def":"to need less than ten minutes"},{"en":"audiologist","tr":"odyolog","ex":"Many clinics don't have enough audiologists.","def":"a health expert who tests and treats hearing"},{"en":"paying customer","tr":"ücretli müşteri, ödeme yapan müşteri","ex":"We've signed five paying customers.","def":"a customer who really pays for your product"},{"en":"so far","tr":"şimdiye kadar","ex":"We've signed five customers so far.","def":"until now"},{"en":"which is why","tr":"bu yüzden, işte bu nedenle","ex":"We need partners in Europe, which is why I'm here.","def":"used to give the result of what you just said"}],"grammar":{"title":"Present perfect: results until now","tr":"'have/has + V3' ile geçmişte olup bugüne sonucu uzanan şeyleri anlatırız. Ne zaman olduğu değil, sonuç önemlidir; 'so far' ve 'already' ile sık kullanılır.","examples":["We've built a device that tests hearing automatically.","So far, we've signed five paying customers."]},"questions":[{"q":"What does the patient do during the test?","options":["Talks to a doctor","Presses a button when they hear a sound","Writes down the results"],"a":1},{"q":"How long does the test take?","options":["Under ten minutes","About an hour","Two days"],"a":0},{"q":"Why do clinics need this device?","options":["It is cheaper than headphones","The government tells them to buy it","They don't have enough audiologists"],"a":2},{"q":"Why is the speaker at this meeting?","options":["To hire an engineer","To find partners in Europe","To sell the company"],"a":1}],"gaps":[{"s":"The test takes under ten ___.","a":"minutes","hint":"dakika"},{"s":"So far, we've ___ five paying customers.","a":"signed","hint":"anlaştık"},{"s":"Many clinics don't have enough ___.","a":"audiologists","hint":"odyologlar"}],"order":[{"a":"The test takes under ten minutes."},{"a":"Our next step is to find partners in Europe."}],"translate":[{"tr":"Şimdiye kadar beş ücretli müşteriyle anlaştık.","en":"So far, we've signed five paying customers.","keys":["so far","five paying customers"]},{"tr":"Test on dakikadan kısa sürüyor.","en":"The test takes under ten minutes.","keys":["takes","under ten minutes"]}],"roleplay":{"persona":"Potential partner","personaTr":"Olası iş ortağı","scene":"Bir konferansta kahve molasında Almanya'dan bir klinik zinciri yöneticisiyle tanışıyorsun.","turns":[{"ai":"Nice to meet you! So, what exactly does your company do?","aiTr":"Tanıştığımıza memnun oldum! Peki, şirketiniz tam olarak ne yapıyor?","hint":"We're a medical technology startup from Turkey, and we've built a device that tests hearing automatically.","keys":["device","hearing","startup"]},{"ai":"How does the test work for the patient?","aiTr":"Test hasta için nasıl işliyor?","hint":"The patient puts on headphones and presses a button when they hear a sound.","keys":["headphones","button","sound"]},{"ai":"Who buys it, and why?","aiTr":"Kim satın alıyor, neden?","hint":"Hospitals, clinics and hearing aid shops buy it because they don't have enough audiologists.","keys":["hospitals","clinics","audiologists"]},{"ai":"And what brings you to Europe?","aiTr":"Peki sizi Avrupa'ya getiren ne?","hint":"Our next step is to find partners in Europe, which is why I'm here.","keys":["partners","next step","which is why"]}]}},"co-02":{"intro":"Toplantıdan sonra kısa, net ve nazik bir takip e-postası yazıyorsun.","text":[{"en":"Subject: Great to meet you at MedTech Europe","tr":"Konu: MedTech Europe'ta tanıştığımıza çok sevindim"},{"en":"Dear Sarah,","tr":"Sevgili Sarah,"},{"en":"It was great to meet you at the conference yesterday.","tr":"Dün konferansta sizinle tanışmak harikaydı."},{"en":"Thank you for your time and for the interesting conversation about waiting lists.","tr":"Zamanınız ve bekleme listeleri hakkındaki ilginç sohbet için teşekkür ederim."},{"en":"As promised, I'm attaching a short presentation about our autonomous audiometer.","tr":"Söz verdiğim gibi, otonom odyometremiz hakkında kısa bir sunum ekliyorum."},{"en":"I would be happy to arrange a short online demo for your team.","tr":"Ekibiniz için kısa bir çevrimiçi demo ayarlamaktan mutluluk duyarım."},{"en":"Would next Tuesday or Wednesday afternoon work for you?","tr":"Gelecek salı veya çarşamba öğleden sonra size uyar mı?"},{"en":"Please let me know if you have any questions.","tr":"Herhangi bir sorunuz olursa lütfen bana bildirin."},{"en":"I look forward to hearing from you.","tr":"Sizden haber almayı dört gözle bekliyorum."},{"en":"Best regards, {name}","tr":"Saygılarımla, {name}"}],"vocab":[{"en":"It was great to meet you.","tr":"Sizinle tanışmak harikaydı.","ex":"It was great to meet you yesterday.","def":"a friendly way to start an email after meeting someone"},{"en":"as promised","tr":"söz verildiği gibi","ex":"As promised, I'm attaching the file.","def":"in the way that you said you would"},{"en":"attach","tr":"eklemek (dosya)","ex":"I'm attaching a short presentation.","def":"to add a file to an email"},{"en":"I would be happy to","tr":"...maktan mutluluk duyarım","ex":"I would be happy to arrange a demo.","def":"a polite way to offer to do something"},{"en":"arrange","tr":"ayarlamak, düzenlemek","ex":"Let's arrange a meeting for next week.","def":"to plan and organise something"},{"en":"Would ... work for you?","tr":"... size uyar mı?","ex":"Would Tuesday afternoon work for you?","def":"a polite way to suggest a time"},{"en":"let me know","tr":"bana bildirin","ex":"Please let me know if you have any questions.","def":"tell me"},{"en":"look forward to hearing from you","tr":"sizden haber almayı dört gözle beklemek","ex":"I look forward to hearing from you soon.","def":"a polite way to end an email when you expect a reply"}],"grammar":{"title":"Polite forms with would","tr":"E-postada doğrudan istemek yerine 'would' kullanmak daha kibar durur: 'I would be happy to…', 'Would … work for you?'. Böylece teklifin ve sorun nazik görünür.","examples":["I would be happy to arrange a short online demo.","Would next Tuesday work for you?","Would you like to see the device?"]},"questions":[{"q":"Why is the writer sending this email?","options":["To complain about the conference","To ask for money","To follow up after meeting at the conference"],"a":2},{"q":"What is attached to the email?","options":["A short presentation","A contract","A price list"],"a":0},{"q":"What does the writer offer?","options":["A free device","A short online demo","Dinner in London"],"a":1},{"q":"Which days does the writer suggest?","options":["Saturday morning","Monday or Friday","Next Tuesday or Wednesday afternoon"],"a":2}],"gaps":[{"s":"As ___, I'm attaching a short presentation.","a":"promised","hint":"söz verildiği gibi"},{"s":"I would be happy to ___ a short online demo.","a":"arrange","hint":"ayarlamak"},{"s":"I look forward to ___ from you.","a":"hearing","hint":"haber almak"}],"order":[{"a":"It was great to meet you at the conference."},{"a":"Would next Tuesday work for you?"}],"translate":[{"tr":"Zamanınız için teşekkür ederim.","en":"Thank you for your time.","keys":["thank","time"]},{"tr":"Herhangi bir sorunuz olursa lütfen bana bildirin.","en":"Please let me know if you have any questions.","keys":["let me know","questions"]}],"roleplay":{"persona":"Sarah (by email)","personaTr":"Sarah (e-posta ile)","scene":"Sarah e-postana cevap veriyor. Sen de kısa ve kibar cevaplar yazıyorsun.","turns":[{"ai":"Hi {name}, thanks for your email and the presentation. A demo sounds good. When are you free?","aiTr":"Merhaba {name}, e-postanız ve sunum için teşekkürler. Demo iyi fikir. Ne zaman müsaitsiniz?","hint":"Thank you, Sarah. Would next Tuesday or Wednesday afternoon work for you?","keys":["would","work for you","Tuesday","afternoon"]},{"ai":"Wednesday at 2 pm works. Who should join from our side?","aiTr":"Çarşamba 14:00 uygun. Bizim taraftan kim katılmalı?","hint":"Great. I would suggest your clinic manager and an audiologist. I will send a calendar invitation.","keys":["suggest","send","invitation","great"]},{"ai":"Perfect, see you then.","aiTr":"Mükemmel, görüşmek üzere.","hint":"Perfect. Please let me know if you have any questions before the demo. Best regards, {name}","keys":["let me know","questions","best regards","look forward"]}]}},"fu-01":{"intro":"Bir sağlık teknolojisi konferansında panelistsin; şüpheci bir doktor, yapay zekânın doktorların yerini alıp almayacağını soruyor.","text":[{"who":"Dr. Weber","en":"I've heard many times that AI will replace doctors, so should I start looking for a new job?","tr":"Yapay zekânın doktorların yerini alacağını defalarca duydum; yeni bir iş aramaya başlamalı mıyım?"},{"who":"Me","en":"I don't think you should, because AI should support doctors, not replace them.","tr":"Bence gerek yok, çünkü yapay zekâ doktorların yerini almamalı, onları desteklemeli."},{"who":"Me","en":"It's true that AI is very fast, and it never gets tired, even at three in the morning.","tr":"Yapay zekânın çok hızlı olduğu ve gece üçte bile yorulmadığı doğru."},{"who":"Me","en":"However, it still makes mistakes, and it's only as good as the data it learns from.","tr":"Ancak yine de hata yapıyor ve ancak öğrendiği veri kadar iyi."},{"who":"Me","en":"If the data is poor, the results will be poor too.","tr":"Veri kötüyse sonuçlar da kötü olur."},{"who":"Me","en":"That's why responsibility has to stay with humans, not with software.","tr":"Bu yüzden sorumluluk yazılımda değil, insanlarda kalmak zorunda."},{"who":"Me","en":"Patients also need someone they can trust, someone who can explain the result and answer their questions.","tr":"Hastaların ayrıca güvenebilecekleri, sonucu açıklayıp sorularını cevaplayabilecek birine ihtiyacı var."},{"who":"Me","en":"Our audiometer runs a hearing test in under ten minutes, with no expert in the room.","tr":"Odyometremiz, odada uzman olmadan on dakikadan kısa sürede bir işitme testi yapıyor."},{"who":"Me","en":"This frees audiologists to spend their time on the complex cases that really need them.","tr":"Bu da odyologlara, gerçekten onlara ihtiyaç duyan karmaşık vakalara zaman ayırma imkânı veriyor."},{"who":"Me","en":"In the end, the doctor still makes the decision, and AI just does the routine work faster.","tr":"Sonuçta kararı yine doktor veriyor; yapay zekâ sadece rutin işi daha hızlı yapıyor."}],"vocab":[{"en":"replace","tr":"yerini almak","ex":"AI will not replace doctors.","def":"to take the place of someone or something"},{"en":"support","tr":"desteklemek","ex":"AI should support doctors in their work.","def":"to help someone do their work"},{"en":"make mistakes","tr":"hata yapmak","ex":"AI still makes mistakes.","def":"to do something wrong without meaning to"},{"en":"only as good as","tr":"ancak ... kadar iyi","ex":"AI is only as good as its data.","def":"no better than the thing it depends on"},{"en":"responsibility","tr":"sorumluluk","ex":"Responsibility has to stay with humans.","def":"the duty to deal with something and to be blamed if it goes wrong"},{"en":"free someone to","tr":"birine ... için zaman açmak","ex":"The device frees audiologists to focus on complex cases.","def":"to give someone time to do something else"},{"en":"complex case","tr":"karmaşık vaka","ex":"Audiologists spend more time on complex cases.","def":"a medical situation that is difficult to understand or treat"},{"en":"routine work","tr":"rutin iş","ex":"AI does the routine work faster.","def":"simple work that is done the same way every time"}],"grammar":{"title":"should / have to: advice and obligation","tr":"'Should' tavsiye ve görüş bildirir: AI should support doctors. 'Have to' zorunluluk anlatır: responsibility has to stay with humans. Soru biçimi: 'Should I…?'","examples":["AI should support doctors, not replace them.","Responsibility has to stay with humans.","Should I start looking for a new job?"]},"questions":[{"q":"What is the speaker's main opinion?","options":["AI will replace doctors soon","AI should support doctors, not replace them","AI is too dangerous for hospitals"],"a":1},{"q":"What happens if the data is poor?","options":["The AI gets tired","The test takes longer","The results will be poor"],"a":2},{"q":"Why do patients need a human?","options":["To explain the result and answer questions","To press the button","To repair the device"],"a":0},{"q":"How does the audiometer help audiologists?","options":["It replaces them","It writes their reports","It sells their services","It frees them for complex cases"],"a":3}],"gaps":[{"s":"AI is only as good as the ___ it learns from.","a":"data","hint":"veri"},{"s":"Responsibility has to ___ with humans.","a":"stay","hint":"kalmak"},{"s":"This frees audiologists to spend time on ___ cases.","a":"complex","hint":"karmaşık"}],"order":[{"a":"AI should support doctors not replace them."},{"a":"The doctor still makes the decision."}],"translate":[{"tr":"Yapay zekâ ancak öğrendiği veri kadar iyidir.","en":"AI is only as good as the data it learns from.","keys":["only as good as","data"]},{"tr":"Sorumluluk insanlarda kalmak zorunda.","en":"Responsibility has to stay with humans.","keys":["responsibility","has to stay"]}],"roleplay":{"persona":"Skeptical doctor on the panel","personaTr":"Paneldeki şüpheci doktor","scene":"Panelde şüpheci bir doktor yapay zekâyı sorguluyor. Görüşünü örneklerle savunuyorsun.","turns":[{"ai":"Be honest: will AI replace doctors like me?","aiTr":"Dürüst olun: yapay zekâ benim gibi doktorların yerini alacak mı?","hint":"I don't think so. AI should support doctors, not replace them.","keys":["support doctors","not replace","don't think so"]},{"ai":"But AI makes mistakes. Who is responsible then?","aiTr":"Ama yapay zekâ hata yapıyor. O zaman kim sorumlu?","hint":"That's exactly why responsibility has to stay with humans, with the doctor.","keys":["responsibility","stay with humans","doctor"]},{"ai":"Then why should a clinic use AI at all?","aiTr":"O zaman bir klinik neden yapay zekâ kullansın ki?","hint":"Because it's fast and never gets tired, so it can do the routine work.","keys":["fast","never gets tired","routine work"]},{"ai":"Give me a real example.","aiTr":"Bana gerçek bir örnek verin.","hint":"Our audiometer runs a hearing test in under ten minutes, so audiologists have more time for complex cases.","keys":["under ten minutes","complex cases","more time"]}]}},"ab-01":{"intro":"Berlin'de bir daireyi geziyorsun; kira, faturalar, depozito, sözleşme ve gerekli belgeler hakkında konuşuyorsun.","text":[{"who":"Landlord","en":"Welcome, I'm Mrs Becker, and I've just renovated the kitchen and the bathroom.","tr":"Hoş geldiniz, ben Bayan Becker; mutfağı ve banyoyu yeni yeniledim."},{"who":"Me","en":"It looks great, and I've never seen such a bright flat in Berlin.","tr":"Harika görünüyor; Berlin'de bu kadar aydınlık bir daire hiç görmedim."},{"who":"Me","en":"Could you tell me what the rent includes?","tr":"Kiraya nelerin dahil olduğunu söyleyebilir misiniz?"},{"who":"Landlord","en":"The rent is €1,200 a month, including heating and water, but you'll have to set up the internet yourself.","tr":"Kira ısınma ve su dahil ayda 1.200 avro, ama interneti kendiniz bağlatmanız gerekecek."},{"who":"Landlord","en":"I ask for a deposit of three months' rent, which is €3,600.","tr":"Üç aylık kira tutarında depozito istiyorum, yani 3.600 avro."},{"who":"Me","en":"That's quite a lot, so would it be possible to pay it in three monthly instalments?","tr":"Bu epey fazla; üç aylık taksitte ödemem mümkün olur mu?"},{"who":"Landlord","en":"That's fine, and in fact, it's quite common here.","tr":"Olur; aslında burada bu oldukça yaygın."},{"who":"Me","en":"How long is the contract, and when is the flat available?","tr":"Sözleşme ne kadar süreli ve daire ne zaman boş?"},{"who":"Landlord","en":"It's a two-year contract, and if you sign this week, you can move in on 1 November.","tr":"İki yıllık bir sözleşme; bu hafta imzalarsanız 1 Kasım'da taşınabilirsiniz."},{"who":"Landlord","en":"I'll need your passport, proof of income and, since you run a company, your company registration papers.","tr":"Pasaportunuza, gelir belgenize ve bir şirket yönettiğiniz için şirket tescil belgelerinize ihtiyacım olacak."}],"vocab":[{"en":"renovate","tr":"yenilemek, tadilat yapmak","ex":"I've just renovated the kitchen.","def":"to repair and improve a building or room"},{"en":"set up the internet","tr":"interneti bağlatmak","ex":"You'll have to set up the internet yourself.","def":"to arrange an internet connection for your home"},{"en":"deposit","tr":"depozito","ex":"I ask for a deposit of three months' rent.","def":"money you pay before you move in and get back when you leave"},{"en":"monthly instalments","tr":"aylık taksitler","ex":"Can I pay it in three monthly instalments?","def":"equal parts of a payment that you pay once a month"},{"en":"available","tr":"boş, müsait","ex":"When is the flat available?","def":"free to be used or rented"},{"en":"move in","tr":"taşınmak","ex":"You can move in on 1 November.","def":"to start living in a new home"},{"en":"proof of income","tr":"gelir belgesi","ex":"I'll need your passport and proof of income.","def":"a document that shows how much money you earn"},{"en":"company registration papers","tr":"şirket tescil belgeleri","ex":"I can send you my company registration papers.","def":"official documents that show a company legally exists"}],"grammar":{"title":"First conditional: if + present, will/can","tr":"Gerçek ve olası bir durumu anlatırken 'if + present simple', ardından 'will/can + fiil' kullanırız. 'If' cümlesinde 'will' kullanılmaz.","examples":["If you sign this week, you can move in on 1 November.","If I pay in instalments, it will be easier for me.","If the street is noisy, I'll close the window."]},"questions":[{"q":"How does the landlord react to the instalment request?","options":["She refuses","She agrees and says it is common","She asks for a higher deposit"],"a":1},{"q":"What does the new tenant have to arrange alone?","options":["Heating","Water","The internet","The deposit"],"a":2},{"q":"When can the tenant move in if they sign this week?","options":["1 November","1 October","1 December"],"a":0},{"q":"Why does the landlord ask for company papers?","options":["Because the rent is high","Because the flat is new","Because the tenant runs a company"],"a":2}],"gaps":[{"s":"You'll have to ___ the internet yourself.","a":"set up","hint":"bağlatmak, kurmak"},{"s":"Would it be possible to pay it in three monthly ___?","a":"instalments","hint":"taksitler"},{"s":"If you sign this week, you can ___ on 1 November.","a":"move in","hint":"taşınmak"}],"order":[{"a":"I've never seen such a bright flat in Berlin."},{"a":"It's quite common to pay in instalments here."}],"translate":[{"tr":"Isınma ve su kiraya dahil, ama interneti kendiniz bağlatmanız gerekecek.","en":"Heating and water are included in the rent, but you'll have to set up the internet yourself.","keys":["included","have to set up","internet"]},{"tr":"Bu hafta imzalarsanız 1 Kasım'da taşınabilirsiniz.","en":"If you sign this week, you can move in on 1 November.","keys":["if you sign","move in"]}],"roleplay":{"persona":"Landlord","personaTr":"Ev sahibi","scene":"Daireyi gezdikten sonra ev sahibi Bayan Becker'le koridorda konuşuyorsun.","turns":[{"ai":"So, have you looked around? What do you think?","aiTr":"Eee, etrafa baktınız mı? Ne düşünüyorsunuz?","hint":"Yes, I have, and I really like it because it's so bright.","keys":["like","bright","really"]},{"ai":"Do you have any pets? Cats are fine, but I'm afraid dogs aren't allowed.","aiTr":"Evcil hayvanınız var mı? Kedi sorun değil ama maalesef köpeğe izin yok.","hint":"No, I don't have any pets, so that's not a problem.","keys":["no","pets","not a problem"]},{"ai":"Do you have any other questions?","aiTr":"Başka sorunuz var mı?","hint":"Yes, is it noisy here at night?","keys":["noisy","quiet","at night"]},{"ai":"The bedroom faces the courtyard, so it's quiet, but the bar on the corner can be loud on Fridays. Is that OK?","aiTr":"Yatak odası avluya bakıyor, o yüzden sessiz; ama köşedeki bar cuma günleri gürültülü olabiliyor. Sizin için sorun olur mu?","hint":"That's fine, and if I take the flat, I'll send you my documents tomorrow.","keys":["fine","documents","send"]}]}},"ab-02":{"intro":"Berlin'de bankada kişisel hesap açıyorsun ve şirket hesabıyla farkını, ücretleri ve kartın nasıl geleceğini öğreniyorsun.","text":[{"who":"Clerk","en":"Good morning, how can I help?","tr":"Günaydın, nasıl yardımcı olabilirim?"},{"who":"Me","en":"I've just moved to Berlin, and I'd like to open a personal account.","tr":"Berlin'e yeni taşındım ve kişisel bir hesap açmak istiyorum."},{"who":"Clerk","en":"Of course, but first, have you registered your address with the city yet?","tr":"Tabii, ama önce şunu sorayım: adresinizi belediyeye kaydettirdiniz mi?"},{"who":"Me","en":"Yes, I have, and I've brought the registration certificate, my passport and my residence permit.","tr":"Evet, kaydettirdim; adres kayıt belgemi, pasaportumu ve oturma iznimi getirdim."},{"who":"Clerk","en":"Perfect, that's everything we need for a personal account.","tr":"Mükemmel, kişisel hesap için ihtiyacımız olan her şey bu."},{"who":"Me","en":"I'd also like to open a business account for my company, if that's possible.","tr":"Mümkünse şirketim için bir ticari hesap da açmak istiyorum."},{"who":"Clerk","en":"For a business account, you have to show papers from the commercial register, and it costs €15 a month.","tr":"Ticari hesap için ticaret sicilinden belgeler göstermeniz gerekiyor ve aylık ücreti 15 avro."},{"who":"Me","en":"The registration isn't finished yet, so I'll come back for that next week.","tr":"Tescil henüz bitmedi, o yüzden onun için gelecek hafta tekrar geleceğim."},{"who":"Clerk","en":"Your personal account is free if at least €1,000 comes in each month; otherwise, it's €5.","tr":"Her ay en az 1.000 avro gelirse kişisel hesabınız ücretsiz; aksi takdirde 5 avro."},{"who":"Clerk","en":"Your debit card will arrive by post within five working days, and the PIN will follow in a separate letter.","tr":"Banka kartınız beş iş günü içinde postayla gelecek, şifreniz de ardından ayrı bir mektupla gelecek."}],"vocab":[{"en":"personal account","tr":"kişisel hesap","ex":"I'd like to open a personal account.","def":"a bank account for your own private money"},{"en":"business account","tr":"ticari hesap, şirket hesabı","ex":"My company needs a business account.","def":"a bank account used by a company"},{"en":"registration certificate","tr":"adres kayıt belgesi","ex":"I've brought my registration certificate.","def":"an official paper that shows where you live"},{"en":"residence permit","tr":"oturma izni","ex":"Here is my residence permit.","def":"an official document that allows you to live in a country"},{"en":"commercial register","tr":"ticaret sicili","ex":"Our company isn't in the commercial register yet.","def":"an official list of the companies in a country"},{"en":"come in","tr":"(hesaba) gelmek, yatmak","ex":"If €1,000 comes in each month, the account is free.","def":"to be paid into an account"},{"en":"working days","tr":"iş günleri","ex":"The card arrives within five working days.","def":"days when offices are open, usually Monday to Friday"},{"en":"follow","tr":"ardından gelmek","ex":"The PIN will follow in a separate letter.","def":"to come after something else"}],"grammar":{"title":"Present perfect: just, yet, already","tr":"Şimdiyle bağlantılı geçmiş eylemler için 'have/has + V3' kullanırız. 'Just' yeni olmuş bir şey, soruda 'yet' 'henüz/şimdiye kadar', 'already' ise 'çoktan' anlamındadır.","examples":["I've just moved to Berlin.","Have you registered your address yet?","I've already brought my passport."]},"questions":[{"q":"What does the clerk ask first?","options":["Whether the speaker has registered their address","How much money they earn","Where they work"],"a":0},{"q":"Why can't the speaker open a business account today?","options":["They don't have a residence permit","The company registration isn't finished","The bank doesn't offer them"],"a":1},{"q":"How much does the business account cost?","options":["€5 a month","Nothing","€15 a month"],"a":2},{"q":"What will arrive after the debit card?","options":["A new passport","The PIN","The registration certificate"],"a":1}],"gaps":[{"s":"Have you registered your address with the city ___?","a":"yet","hint":"henüz"},{"s":"You have to show papers from the commercial ___.","a":"register","hint":"sicil"},{"s":"Your card will arrive within five ___ days.","a":"working","hint":"iş (günü)"}],"order":[{"a":"I've just moved to Berlin."},{"a":"The PIN will follow in a separate letter."}],"translate":[{"tr":"Adres kayıt belgemi, pasaportumu ve oturma iznimi getirdim.","en":"I've brought my registration certificate, my passport and my residence permit.","keys":["brought","registration certificate","residence permit"]},{"tr":"Tescil henüz bitmedi, o yüzden gelecek hafta tekrar geleceğim.","en":"The registration isn't finished yet, so I'll come back next week.","keys":["isn't finished yet","come back"]}],"roleplay":{"persona":"Bank clerk","personaTr":"Banka memuru","scene":"Bankada sıra sana geldi. Memur sana adres kaydını ve internet bankacılığını soruyor.","turns":[{"ai":"Good morning! What can I do for you today?","aiTr":"Günaydın! Bugün sizin için ne yapabilirim?","hint":"Good morning, I've just moved to Berlin and I'd like to open a personal account.","keys":["open","personal account","just moved"]},{"ai":"Have you registered your address yet?","aiTr":"Adresinizi kaydettirdiniz mi?","hint":"Yes, I have, and here is my registration certificate.","keys":["yes, I have","registration certificate","registered"]},{"ai":"Would you like to use online banking as well?","aiTr":"İnternet bankacılığını da kullanmak ister misiniz?","hint":"Yes, please, so how do I set up the app?","keys":["yes","app","set up"]},{"ai":"Just download it, and you'll get a temporary password by text message. Anything else?","aiTr":"Sadece indirin; kısa mesajla geçici bir şifre alacaksınız. Başka bir şey var mı?","hint":"No, that's all, thank you for your help.","keys":["that's all","thank you","no"]}]}},"ab-04":{"intro":"Komşun Lena ile merdivende tanışıyorsun: hava, nereli olduğun, ne iş yaptığın, Berlin'i neden sevdiğin; pazartesi de Tom'la hafta sonunu konuşuyorsun.","text":[{"who":"Lena","en":"Oh hi, you must be the new neighbour—I'm Lena, from the fourth floor.","tr":"Aa merhaba, yeni komşu sen olmalısın; ben Lena, dördüncü kattan."},{"who":"Me","en":"Nice to meet you, I'm {name}, and I've just moved into the flat below you.","tr":"Tanıştığımıza memnun oldum, ben {name}; senin alt katındaki daireye yeni taşındım."},{"who":"Lena","en":"Finally some sunshine, even if it's freezing—we've had rain all week!","tr":"Nihayet biraz güneş, buz gibi olsa da; bütün hafta yağmur yağdı!"},{"who":"Lena","en":"So, where are you from, and what brings you to Berlin?","tr":"Eee, nerelisin ve seni Berlin'e ne getirdi?"},{"who":"Me","en":"I'm from Istanbul, and I've come here to open the European office of my health-tech startup.","tr":"İstanbulluyum; buraya sağlık teknolojisi girişimimin Avrupa ofisini açmak için geldim."},{"who":"Me","en":"I love how green the city is, but I wasn't ready for the shops to close on Sundays!","tr":"Şehrin bu kadar yeşil olmasına bayılıyorum, ama pazar günleri dükkânların kapanmasına hazır değildim!"},{"who":"Lena","en":"We're having a barbecue in the courtyard on Sunday afternoon, so if you're free, you should come.","tr":"Pazar öğleden sonra avluda mangal yapıyoruz; müsaitsen sen de gelmelisin."},{"who":"Tom","en":"Morning—how was your weekend?","tr":"Günaydın, hafta sonun nasıldı?"},{"who":"Me","en":"Really nice, thanks, I went to my neighbours' barbecue and finally made some friends.","tr":"Çok güzeldi, teşekkürler; komşularımın mangalına gittim ve nihayet birkaç arkadaş edindim."},{"who":"Tom","en":"Great, so if you're free on Friday, come for a drink with the team after work.","tr":"Harika; cuma müsaitsen iş çıkışı ekiple bir şeyler içmeye gel."}],"vocab":[{"en":"move into","tr":"(bir eve) taşınmak","ex":"I've just moved into the flat below you.","def":"to start living in a new home"},{"en":"freezing","tr":"buz gibi, dondurucu","ex":"It's sunny but freezing today.","def":"very cold"},{"en":"what brings you to","tr":"seni ...'e ne getirdi","ex":"What brings you to Berlin?","def":"a friendly way to ask why someone has come to a place"},{"en":"health-tech startup","tr":"sağlık teknolojisi girişimi","ex":"I run a health-tech startup.","def":"a new company that uses technology to improve health care"},{"en":"be ready for","tr":"...e hazır olmak","ex":"I wasn't ready for the shops to close on Sundays.","def":"to be prepared for something"},{"en":"if you're free","tr":"müsaitsen","ex":"If you're free, come to the barbecue.","def":"if you have no other plans"},{"en":"make friends","tr":"arkadaş edinmek","ex":"I've finally made some friends here.","def":"to start new friendships"},{"en":"after work","tr":"iş çıkışı","ex":"Let's go for a drink after work.","def":"when the working day has finished"}],"grammar":{"title":"Present perfect: just, all week","tr":"Yakın zamanda olmuş ve şimdiyi etkileyen olaylar için 'have/has + V3' kullanırız. 'Just' = yeni, az önce; 'all week' gibi ifadeler bugüne kadar süren bir durumu gösterir.","examples":["I've just moved into the flat below you.","We've had rain all week.","I've come here to open our European office."]},"questions":[{"q":"Where does Lena live?","options":["On the fourth floor","On the ground floor","In the flat next door"],"a":0},{"q":"What was the weather like before this weekend?","options":["Sunny all week","Rainy all week","Snowy"],"a":1},{"q":"What surprised the speaker about Berlin?","options":["The parks","The weather","Shops are closed on Sundays"],"a":2},{"q":"What does Tom suggest?","options":["A drink with the team on Friday","A barbecue on Sunday","Lunch on Monday"],"a":0}],"gaps":[{"s":"I've just moved ___ the flat below you.","a":"into","hint":"-e (taşınmak)"},{"s":"We've had rain all ___!","a":"week","hint":"hafta"},{"s":"If you're ___, you should come.","a":"free","hint":"müsait"}],"order":[{"a":"I love how green the city is."},{"a":"I've finally made some friends here."}],"translate":[{"tr":"Seni Berlin'e ne getirdi?","en":"What brings you to Berlin?","keys":["what brings you","Berlin"]},{"tr":"Pazar günleri dükkânların kapanmasına hazır değildim.","en":"I wasn't ready for the shops to close on Sundays.","keys":["wasn't ready for","close on Sundays"]}],"roleplay":{"persona":"Neighbour (Lena)","personaTr":"Komşu (Lena)","scene":"Cumartesi sabahı merdivende dördüncü kattaki komşun Lena ile karşılaşıyorsun ve sohbet başlıyor.","turns":[{"ai":"Hi there, you must be the new neighbour! I'm Lena, from upstairs.","aiTr":"Selam, yeni komşu sen olmalısın! Ben Lena, üst kattan.","hint":"Nice to meet you, Lena, I've just moved into the flat below you.","keys":["nice to meet you","just moved","below"]},{"ai":"So, what brings you to Berlin?","aiTr":"Eee, seni Berlin'e ne getirdi?","hint":"I've come to open the European office of my health-tech startup.","keys":["European office","startup","open"]},{"ai":"And how are you finding it so far? Is it very different from home?","aiTr":"Peki şimdiye kadar nasıl buluyorsun? Memleketinden çok farklı mı?","hint":"I love the parks, but people here are much more direct than in Istanbul.","keys":["love","more direct","parks"]},{"ai":"We're having a barbecue in the courtyard on Sunday. Would you like to come?","aiTr":"Pazar günü avluda mangal yapıyoruz. Gelmek ister misin?","hint":"I'd love to, thank you, and I'll bring some baklava.","keys":["I'd love to","baklava","thank you"]}]}},"ab-03":{"intro":"Telefonla randevu alıyorsun, sonra doktora ağrının ne kadar sürdüğünü, ne kadar kötü olduğunu ve uyku sorununu anlatıyorsun.","text":[{"who":"Receptionist","en":"Dr Hoffmann's practice, good morning, how can I help?","tr":"Dr. Hoffmann'ın muayenehanesi, günaydın, nasıl yardımcı olabilirim?"},{"who":"Me","en":"Hello, I've had back pain for three weeks, and I'd like to see the doctor.","tr":"Merhaba, üç haftadır sırt ağrım var ve doktora görünmek istiyorum."},{"who":"Receptionist","en":"Is it an emergency, or can it wait until Thursday at 9:30?","tr":"Acil bir durum mu, yoksa perşembe saat 9.30'a kadar bekleyebilir mi?"},{"who":"Me","en":"Thursday is fine, thanks, so should I bring anything with me?","tr":"Perşembe uygun, teşekkürler; yanımda bir şey getirmem gerekiyor mu?"},{"who":"Receptionist","en":"Yes, you have to bring your health insurance card.","tr":"Evet, sağlık sigortası kartınızı getirmeniz gerekiyor."},{"who":"Doctor","en":"So, how long have you had the pain, and how bad is it?","tr":"Evet, ne zamandır ağrınız var ve ne kadar kötü?"},{"who":"Me","en":"It's been about three weeks, and in the evening it's around six out of ten.","tr":"Yaklaşık üç hafta oldu; akşamları on üzerinden altı civarında."},{"who":"Me","en":"I've also been sleeping badly, and I often wake up at four in the morning.","tr":"Ayrıca kötü uyuyorum ve sık sık sabah dörtte uyanıyorum."},{"who":"Doctor","en":"Your muscles are very tight, but if you take regular breaks, it should get better.","tr":"Kaslarınız çok gergin, ama düzenli mola verirseniz düzelmesi gerekir."},{"who":"Doctor","en":"Here's a prescription for a pain-relief gel, which you can get at any pharmacy.","tr":"İşte ağrı kesici bir jel için reçete; herhangi bir eczaneden alabilirsiniz."}],"vocab":[{"en":"have back pain","tr":"sırt ağrısı olmak","ex":"I've had back pain for three weeks.","def":"to feel pain in your back"},{"en":"emergency","tr":"acil durum","ex":"Is it an emergency?","def":"a serious situation that needs help immediately"},{"en":"health insurance card","tr":"sağlık sigortası kartı","ex":"You have to bring your health insurance card.","def":"a card that shows you have health insurance"},{"en":"out of ten","tr":"on üzerinden","ex":"The pain is about six out of ten.","def":"used to give a score on a scale from one to ten"},{"en":"wake up","tr":"uyanmak","ex":"I often wake up at four in the morning.","def":"to stop sleeping"},{"en":"take regular breaks","tr":"düzenli mola vermek","ex":"You should take regular breaks from your laptop.","def":"to stop working for a short time again and again"},{"en":"get better","tr":"iyileşmek, düzelmek","ex":"If you rest, it should get better.","def":"to improve, especially after an illness"},{"en":"pain-relief gel","tr":"ağrı kesici jel","ex":"Here's a prescription for a pain-relief gel.","def":"a gel you put on your skin to reduce pain"}],"grammar":{"title":"Present perfect with 'for' and 'How long…?'","tr":"Geçmişte başlayıp hâlâ devam eden durumlar için 'have/has + V3' ve süre için 'for' kullanırız. Türkçedeki '-dır/-dir' gibidir: 'üç haftadır'.","examples":["I've had back pain for three weeks.","How long have you had the pain?","I've been sleeping badly since I started this job."]},"questions":[{"q":"How long has the speaker had back pain?","options":["Three days","About three weeks","Three months"],"a":1},{"q":"How bad is the pain in the evening?","options":["Six out of ten","Two out of ten","Ten out of ten"],"a":0},{"q":"What does the receptionist ask the speaker to bring?","options":["A passport","A prescription","A health insurance card"],"a":2},{"q":"According to the doctor, what will help the back get better?","options":["Working longer","Taking regular breaks","Sleeping less"],"a":1}],"gaps":[{"s":"I've had back pain ___ three weeks.","a":"for","hint":"-dır/-dir (süre)"},{"s":"I often ___ up at four in the morning.","a":"wake","hint":"uyanmak"},{"s":"If you take regular breaks, it should get ___.","a":"better","hint":"daha iyi"}],"order":[{"a":"Is it an emergency or can it wait?"},{"a":"You have to bring your health insurance card."}],"translate":[{"tr":"Üç haftadır sırt ağrım var.","en":"I've had back pain for three weeks.","keys":["I've had","back pain","for three weeks"]},{"tr":"Düzenli mola verirseniz düzelmesi gerekir.","en":"If you take regular breaks, it should get better.","keys":["regular breaks","get better"]}],"roleplay":{"persona":"Doctor","personaTr":"Doktor","scene":"Perşembe sabahı muayenedesin. Dr. Hoffmann ağrını ve uykunu soruyor.","turns":[{"ai":"Good morning, come in and have a seat. What seems to be the problem?","aiTr":"Günaydın, girin, oturun. Sorun ne gibi görünüyor?","hint":"I've had pain in my lower back for three weeks, and I've been sleeping badly.","keys":["lower back","three weeks","sleeping badly"]},{"ai":"I see. How bad is the pain, on a scale from one to ten?","aiTr":"Anlıyorum. Birden ona kadar bir ölçekte ağrı ne kadar kötü?","hint":"It's about six out of ten, especially in the evening.","keys":["six out of ten","evening","six"]},{"ai":"Have you taken anything for it?","aiTr":"Bunun için bir şey aldınız mı?","hint":"Yes, I've taken ibuprofen a few times, but it only helps for a few hours.","keys":["ibuprofen","only helps","taken"]},{"ai":"OK, you should take regular breaks and walk thirty minutes a day. Do you have any questions?","aiTr":"Tamam, düzenli mola vermeli ve günde otuz dakika yürümelisiniz. Sorunuz var mı?","hint":"Yes, should I come back if it doesn't get better?","keys":["come back","doesn't get better","should"]}]}},"li-03":{"intro":"Uyku, odak ve alışkanlıklar üzerinden yoğun girişim temposunu nasıl sürdürülebilir hale getirdiğini anlatıyorsun.","text":[{"who":"Me","en":"In my first year as a founder, I worked fourteen hours a day and slept only five.","tr":"Kurucu olarak ilk yılımda günde on dört saat çalıştım ve sadece beş saat uyudum."},{"who":"Me","en":"I thought this was normal, but then I started making bad decisions.","tr":"Bunun normal olduğunu düşünüyordum ama sonra kötü kararlar vermeye başladım."},{"who":"Me","en":"A tired brain is a slow brain, and it chooses the easy answer, not the right one.","tr":"Yorgun bir beyin yavaş bir beyindir ve doğru cevabı değil, kolay cevabı seçer."},{"who":"Me","en":"Since then, I have changed my routine, and now I have three simple rules.","tr":"O zamandan beri günlük düzenimi değiştirdim ve artık üç basit kuralım var."},{"who":"Me","en":"First, I sleep at least seven hours, and I don't answer emails after ten at night.","tr":"Birincisi, en az yedi saat uyuyorum ve gece ondan sonra e-postalara cevap vermiyorum."},{"who":"Me","en":"Second, I do my most important task in the morning, before meetings, when my mind is fresh.","tr":"İkincisi, en önemli işimi sabah, toplantılardan önce, zihnim dinçken yapıyorum."},{"who":"Me","en":"Third, I walk for thirty minutes every day, and many of my best ideas have come during a walk.","tr":"Üçüncüsü, her gün otuz dakika yürüyorum ve en iyi fikirlerimin çoğu yürüyüş sırasında aklıma geldi."},{"who":"Me","en":"A startup is a marathon, not a sprint.","tr":"Girişim bir sprint değil, maratondur."},{"who":"Me","en":"If the founder burns out, the company will burn out too.","tr":"Kurucu tükenirse şirket de tükenir."}],"vocab":[{"en":"make a bad decision","tr":"kötü karar vermek","ex":"I started making bad decisions.","def":"to choose something that turns out to be wrong"},{"en":"since then","tr":"o zamandan beri","ex":"Since then, I have changed my routine.","def":"from that time until now"},{"en":"routine","tr":"günlük düzen, rutin","ex":"I have changed my routine.","def":"the usual order in which you do things"},{"en":"at least","tr":"en az","ex":"I sleep at least seven hours.","def":"not less than"},{"en":"most important task","tr":"en önemli iş","ex":"I do my most important task first.","def":"the job that matters most on a given day"},{"en":"fresh","tr":"dinç, zinde","ex":"My mind is fresh in the morning.","def":"full of energy, not tired"},{"en":"a marathon, not a sprint","tr":"sprint değil, maraton","ex":"A startup is a marathon, not a sprint.","def":"something that needs long, steady effort, not a quick burst"},{"en":"burn out","tr":"tükenmek","ex":"If the founder burns out, the company burns out too.","def":"to become ill or exhausted from working too hard"}],"grammar":{"title":"Present perfect vs past simple","tr":"Belirli bir geçmiş zaman varsa (in my first year) past simple kullanılır: I worked, I slept. Geçmişten bugüne uzanan değişim ya da deneyim için present perfect kullanılır: I have changed my routine.","examples":["In my first year, I worked fourteen hours a day.","Since then, I have changed my routine.","Many of my best ideas have come during a walk."]},"questions":[{"q":"What happened in the founder's first year?","options":["They slept a lot","They worked 14 hours a day and slept 5","They took a long holiday"],"a":1},{"q":"What does a tired brain do?","options":["It chooses the easy answer","It works faster","It finds the right answer"],"a":0},{"q":"When does the founder do the most important task?","options":["At night","After lunch","In the morning, before meetings"],"a":2},{"q":"What happens if the founder burns out?","options":["Nothing changes","The company burns out too","The company grows faster"],"a":1}],"gaps":[{"s":"A ___ brain is a slow brain.","a":"tired","hint":"yorgun"},{"s":"Since then, I have changed my ___.","a":"routine","hint":"günlük düzen"},{"s":"If the founder burns ___, the company will burn out too.","a":"out","hint":"tükenmek"}],"order":[{"a":"Now I have three simple rules."},{"a":"A startup is a marathon not a sprint."}],"translate":[{"tr":"Her gün otuz dakika yürüyorum.","en":"I walk for thirty minutes every day.","keys":["walk","thirty minutes","every day"]},{"tr":"Kötü kararlar vermeye başladım.","en":"I started making bad decisions.","keys":["started","bad decisions"]}],"roleplay":{"persona":"Young founder","personaTr":"Genç kurucu","scene":"Genç bir girişimci, yoğun tempoyla nasıl baş ettiğini soruyor.","turns":[{"ai":"I work all the time and I'm so tired. How do you manage?","aiTr":"Sürekli çalışıyorum ve çok yorgunum. Sen nasıl idare ediyorsun?","hint":"I had the same problem. A tired brain makes bad decisions, so now I sleep at least seven hours.","keys":["tired brain","bad decisions","at least seven hours"]},{"ai":"But I have too many tasks. When should I do them?","aiTr":"Ama çok fazla işim var. Onları ne zaman yapmalıyım?","hint":"Do your most important task in the morning, before meetings, when your mind is fresh.","keys":["most important task","morning","fresh"]},{"ai":"I feel guilty when I stop working, though.","aiTr":"Ama çalışmayı bırakınca kendimi suçlu hissediyorum.","hint":"I understand, but if you burn out, your company will burn out too.","keys":["burn out","company","understand"]},{"ai":"Do you have any other advice?","aiTr":"Başka bir tavsiyen var mı?","hint":"Walk for thirty minutes every day. A startup is a marathon, not a sprint.","keys":["walk","marathon","sprint","every day"]}]}},"ai-05":{"intro":"Fiyat, kurulum, eğitim, servis ve ücretsiz deneme gibi satış sorularına cevap veriyorsun.","text":[{"who":"Buyer","en":"We're interested in your audiometer, but I need to understand the costs first.","tr":"Odyometrenizle ilgileniyoruz ama önce maliyetleri anlamam gerekiyor."},{"who":"Me","en":"The device costs 4,000 euros, and there's a monthly software fee of 99 euros per clinic.","tr":"Cihaz 4.000 euro ve klinik başına aylık 99 euro yazılım ücreti var."},{"who":"Buyer","en":"That's quite a lot more than a classic audiometer.","tr":"Bu, klasik bir odyometreden epey fazla."},{"who":"Me","en":"That's true, but you don't need an expert for every test, so you'll save time and money every day.","tr":"Doğru ama her test için bir uzmana ihtiyacınız yok, bu yüzden her gün zamandan ve paradan tasarruf edeceksiniz."},{"who":"Buyer","en":"How long does installation take?","tr":"Kurulum ne kadar sürüyor?"},{"who":"Me","en":"About an hour, and we train your staff on the same day.","tr":"Yaklaşık bir saat ve personelinizi aynı gün eğitiyoruz."},{"who":"Buyer","en":"What happens if the device breaks down?","tr":"Cihaz arızalanırsa ne olur?"},{"who":"Me","en":"It comes with a two-year warranty and remote support, and most problems can be fixed with a software update.","tr":"İki yıl garanti ve uzaktan destekle geliyor; çoğu sorun da bir yazılım güncellemesiyle çözülebiliyor."},{"who":"Buyer","en":"Can we try it before we make a decision?","tr":"Karar vermeden önce deneyebilir miyiz?"},{"who":"Me","en":"Of course, and if you're not happy after a free one-month trial, you can simply send it back.","tr":"Tabii ki; bir aylık ücretsiz denemeden sonra memnun kalmazsanız cihazı geri gönderebilirsiniz."}],"vocab":[{"en":"monthly fee","tr":"aylık ücret","ex":"There's a monthly software fee of 99 euros.","def":"money you pay every month for a service"},{"en":"save time and money","tr":"zamandan ve paradan tasarruf etmek","ex":"You'll save time and money every day.","def":"to need less time and spend less money"},{"en":"installation","tr":"kurulum","ex":"Installation takes about an hour.","def":"putting a machine in place and making it ready to use"},{"en":"train the staff","tr":"personeli eğitmek","ex":"We train your staff on the same day.","def":"to teach employees how to do something"},{"en":"break down","tr":"arızalanmak, bozulmak","ex":"What happens if the device breaks down?","def":"(of a machine) to stop working"},{"en":"warranty","tr":"garanti","ex":"It comes with a two-year warranty.","def":"a promise to repair or replace a product if it breaks"},{"en":"remote support","tr":"uzaktan destek","ex":"We offer remote support.","def":"help that is given online or by phone, not in person"},{"en":"free trial","tr":"ücretsiz deneme","ex":"We can set up a free one-month trial.","def":"a period when you can use a product without paying"}],"grammar":{"title":"First conditional: if + present, will / can","tr":"Gerçekleşmesi mümkün durumlar için: If + present simple, will/can + fiil. Satışta müşteriye ne olacağını anlatmak için çok kullanılır.","examples":["If you're not happy, you can send it back.","If the device breaks down, we'll fix it remotely.","If you buy it, you'll save time every day."]},"questions":[{"q":"How much is the monthly software fee?","options":["99 euros per clinic","4,000 euros","Nothing in the first year"],"a":0},{"q":"Why does the founder say the price is worth it?","options":["The device looks modern","Clinics don't need an expert for every test","It's the cheapest on the market"],"a":1},{"q":"How long does installation take?","options":["About a day","About a week","About an hour"],"a":2},{"q":"What can the hospital do if it's not happy after the trial?","options":["Ask for a discount","Get a second device","Extend the warranty","Send the device back"],"a":3}],"gaps":[{"s":"There's a monthly software ___ of 99 euros.","a":"fee","hint":"ücret"},{"s":"We train your ___ on the same day.","a":"staff","hint":"personel"},{"s":"Most problems can be fixed with a software ___.","a":"update","hint":"güncelleme"}],"order":[{"a":"How long does installation take?"},{"a":"It comes with a two-year warranty and remote support."}],"translate":[{"tr":"Her gün zamandan ve paradan tasarruf edeceksiniz.","en":"You'll save time and money every day.","keys":["save time and money","every day"]},{"tr":"Memnun kalmazsanız cihazı geri gönderebilirsiniz.","en":"If you're not happy, you can send the device back.","keys":["if you're not happy","send"]}],"roleplay":{"persona":"Hospital buyer","personaTr":"Hastane satın alma yöneticisi","scene":"Yabancı bir özel hastanenin satın alma yöneticisiyle görüşüyorsun.","turns":[{"ai":"We like your product. What does it cost?","aiTr":"Ürününüzü beğendik. Fiyatı ne kadar?","hint":"The device costs 4,000 euros, and there's a monthly software fee of 99 euros.","keys":["4,000","monthly","fee","euros"]},{"ai":"Hmm, that's expensive. Why should we pay more?","aiTr":"Hmm, bu pahalı. Neden daha fazla ödeyelim?","hint":"Because you don't need an expert for every test, so you'll save time and money every day.","keys":["expert","save","time and money"]},{"ai":"What if it breaks down?","aiTr":"Ya arızalanırsa?","hint":"It comes with a two-year warranty and remote support, and most problems can be fixed with a software update.","keys":["warranty","remote support","software update"]},{"ai":"Can we test it first?","aiTr":"Önce test edebilir miyiz?","hint":"Of course. We can set up a free one-month trial.","keys":["free","trial","of course"]}]}},"li-02":{"intro":"İnsanların neden hayır dediğini ve bunu nasıl değiştirebileceğini anlatıyorsun: güven, anlaşılırlık ve zamanlama.","text":[{"who":"Me","en":"I have learned that when a customer says no, it is usually not about the product.","tr":"Şunu öğrendim: bir müşteri hayır dediğinde, bu genellikle ürünle ilgili değildir."},{"who":"Me","en":"People say no for three main reasons: they don't trust you, they don't understand you, or the timing is wrong.","tr":"İnsanlar üç ana nedenle hayır der: size güvenmezler, sizi anlamazlar ya da zamanlama yanlıştır."},{"who":"Me","en":"Trust comes from small signals, like a clear website, a quick reply or a customer who recommends you.","tr":"Güven küçük işaretlerden gelir: net bir web sitesi, hızlı bir cevap ya da sizi tavsiye eden bir müşteri gibi."},{"who":"Me","en":"Understanding comes from simple language: if a buyer needs an engineer to understand your pitch, you have already lost.","tr":"Anlaşılmak sade bir dilden geçer: bir alıcı sunumunuzu anlamak için mühendise ihtiyaç duyuyorsa, zaten kaybetmişsinizdir."},{"who":"Me","en":"Timing is about pain, because people only change when the old way becomes too painful.","tr":"Zamanlama sıkıntıyla ilgilidir, çünkü insanlar ancak eski yöntem fazla zahmetli hale gelince değişir."},{"who":"Me","en":"That's why I ask myself three questions before every meeting.","tr":"Bu yüzden her toplantıdan önce kendime üç soru sorarım."},{"who":"Me","en":"Why should they trust me, will they understand me in one minute, and what is their pain today?","tr":"Bana neden güvensinler, beni bir dakikada anlayacaklar mı ve bugünkü sıkıntıları ne?"},{"who":"Me","en":"Last year, a clinic said no to us, but we stayed in contact and asked again three months later.","tr":"Geçen yıl bir klinik bize hayır dedi, ama iletişimde kaldık ve üç ay sonra tekrar sorduk."},{"who":"Me","en":"Their waiting list was much longer by then, and this time they said yes.","tr":"O zamana kadar bekleme listeleri çok uzamıştı ve bu sefer evet dediler."},{"who":"Me","en":"In the end, a 'no' today is often just a 'not yet'.","tr":"Sonuçta bugünkü bir 'hayır' çoğu zaman sadece 'henüz değil' demektir."}],"vocab":[{"en":"main reason","tr":"ana neden","ex":"People say no for three main reasons.","def":"the most important cause of something"},{"en":"signal","tr":"işaret","ex":"A quick reply is a strong signal.","def":"something that shows what is true or what will happen"},{"en":"recommend","tr":"tavsiye etmek","ex":"A happy customer recommends you to others.","def":"to tell people that someone or something is good"},{"en":"pitch","tr":"tanıtım konuşması, sunum","ex":"Can a buyer understand your pitch in one minute?","def":"a short talk that tries to persuade someone to buy or invest"},{"en":"timing","tr":"zamanlama","ex":"The timing was wrong last year.","def":"the moment when something happens or is done"},{"en":"painful","tr":"zahmetli, can sıkıcı","ex":"People change when the old way becomes too painful.","def":"causing a lot of trouble or difficulty"},{"en":"stay in contact","tr":"iletişimde kalmak","ex":"We stayed in contact and asked again.","def":"to keep talking or writing to someone over time"},{"en":"not yet","tr":"henüz değil","ex":"A 'no' today is often a 'not yet'.","def":"not now, but maybe later"}],"grammar":{"title":"Present perfect vs past simple","tr":"Present perfect (have/has + V3), ne zaman olduğu önemli olmayan ve bugüne etkisi süren deneyimler için kullanılır: 'I have learned', 'you have already lost'. Belirli bir geçmiş zaman varsa (last year) past simple kullanılır.","examples":["I have learned that a 'no' is usually not about the product.","If a buyer needs an engineer, you have already lost.","Last year, a clinic said no to us."]},"questions":[{"q":"What are the three reasons people say no?","options":["Price, colour and size","Weather, mood and luck","Trust, understanding and timing"],"a":2},{"q":"Where does trust come from?","options":["Small signals like quick replies","Big offices","Long contracts"],"a":0},{"q":"Why did the clinic say yes the second time?","options":["The price was lower","Their waiting list was much longer","A new manager arrived"],"a":1},{"q":"What does the speaker do before every meeting?","options":["Calls the customer","Lowers the price","Writes a long email","Asks three questions"],"a":3}],"gaps":[{"s":"Trust comes from small ___, like a quick reply.","a":"signals","hint":"işaretler"},{"s":"If a buyer needs an engineer to understand your ___, you have already lost.","a":"pitch","hint":"sunum"},{"s":"We stayed in ___ and asked again three months later.","a":"contact","hint":"iletişim"}],"order":[{"a":"Understanding comes from simple language."},{"a":"A no today is often just a not yet."}],"translate":[{"tr":"Bana neden güvensinler?","en":"Why should they trust me?","keys":["why should","trust"]},{"tr":"Zamanlama yanlıştı ama iletişimde kaldık.","en":"The timing was wrong, but we stayed in contact.","keys":["timing","stayed in contact"]}],"roleplay":{"persona":"Hesitant clinic owner","personaTr":"Kararsız klinik sahibi","scene":"Klinik sahibi 'şimdi değil' diyor. Nedenini anlamaya ve iletişimi sürdürmeye çalışıyorsun.","turns":[{"ai":"It's a nice device, but I don't think we're ready. Maybe next year.","aiTr":"Güzel bir cihaz ama sanırım hazır değiliz. Belki seneye.","hint":"I understand. Can I ask what the biggest problem is for you today?","keys":["understand","biggest problem","ask"]},{"ai":"Honestly, our patients wait six weeks for a test. But a new device is a risk.","aiTr":"Açıkçası hastalarımız test için altı hafta bekliyor. Ama yeni bir cihaz risk demek.","hint":"Six weeks is a long wait. What if you try the device free for one month, with no risk?","keys":["what if","free","one month","no risk"]},{"ai":"Hmm. Let me think about it.","aiTr":"Hmm. Bir düşüneyim.","hint":"Of course. I'll stay in contact and send you a short email next week.","keys":["stay in contact","email","next week","of course"]}]}},"st-04":{"intro":"Komisyon, süre ve münhasırlık şartları üzerinde pazarlık yaparken nazik ama net oluyorsun.","text":[{"who":"Partner","en":"Our standard commission is 25 percent on every device we sell.","tr":"Standart komisyonumuz sattığımız her cihaz için yüzde 25."},{"who":"Me","en":"Thank you for the offer, but 25 percent is a bit high for us.","tr":"Teklif için teşekkürler ama yüzde 25 bizim için biraz yüksek."},{"who":"Me","en":"Our production costs are quite high, so we can't go above 15 percent.","tr":"Üretim maliyetlerimiz oldukça yüksek, bu yüzden yüzde 15'in üstüne çıkamayız."},{"who":"Partner","en":"I'm afraid fifteen won't work for us, because we also have to cover our marketing costs.","tr":"Korkarım on beş bizim için olmaz, çünkü bizim de pazarlama masraflarımızı karşılamamız gerekiyor."},{"who":"Me","en":"I understand, so what if we meet in the middle at 20 percent for the first year?","tr":"Anlıyorum, peki ilk yıl için yüzde 20'de ortada buluşsak nasıl olur?"},{"who":"Me","en":"We can review the agreement after twelve months and adjust it if we need to.","tr":"On iki ay sonra anlaşmayı gözden geçirip gerekirse değiştirebiliriz."},{"who":"Partner","en":"That sounds fair, but we'd also like exclusive rights in Germany.","tr":"Bu adil görünüyor ama Almanya'da münhasır haklar da istiyoruz."},{"who":"Me","en":"We can agree to exclusive rights, as long as you reach a minimum sales target.","tr":"Minimum bir satış hedefine ulaştığınız sürece münhasır hakları kabul edebiliriz."},{"who":"Partner","en":"OK, let's put everything in writing and sign next week.","tr":"Tamam, her şeyi yazıya dökelim ve gelecek hafta imzalayalım."},{"who":"Me","en":"Perfect, I think we've reached an agreement.","tr":"Mükemmel, sanırım bir anlaşmaya vardık."}],"vocab":[{"en":"a bit high","tr":"biraz yüksek","ex":"25 percent is a bit high for us.","def":"slightly more than you want to pay"},{"en":"I'm afraid","tr":"korkarım, maalesef","ex":"I'm afraid fifteen won't work for us.","def":"a polite way to say something negative"},{"en":"cover costs","tr":"masrafları karşılamak","ex":"We have to cover our marketing costs.","def":"to have enough money to pay for something"},{"en":"meet in the middle","tr":"ortada buluşmak","ex":"What if we meet in the middle at 20 percent?","def":"to agree on something between two positions"},{"en":"review the agreement","tr":"anlaşmayı gözden geçirmek","ex":"We can review the agreement after twelve months.","def":"to look at a deal again and maybe change it"},{"en":"exclusive rights","tr":"münhasır haklar (tek satıcılık)","ex":"They'd like exclusive rights in Germany.","def":"the right to be the only company that sells something in a place"},{"en":"as long as","tr":"...dığı sürece","ex":"We agree, as long as you reach the target.","def":"only if"},{"en":"reach an agreement","tr":"anlaşmaya varmak","ex":"I think we've reached an agreement.","def":"to finally agree after discussing"}],"grammar":{"title":"Polite suggestions and conditions: what if / as long as","tr":"'What if we…?' ile nazikçe yeni bir öneri sunarız. 'As long as' (…dığı sürece) ile bir koşul koyarız; anlaşmayı kabul ederken sınırını belirlemiş olursun.","examples":["What if we meet in the middle at 20 percent?","We can agree to exclusive rights, as long as you reach a minimum sales target."]},"questions":[{"q":"What was the distributor's first offer?","options":["15 percent","25 percent","20 percent"],"a":1},{"q":"Why does the distributor say no to 15 percent?","options":["They have to cover their marketing costs","They don't trust the startup","They want to sell in Turkey"],"a":0},{"q":"When will they review the agreement?","options":["After six months","After two years","After twelve months"],"a":2},{"q":"What is the condition for exclusive rights in Germany?","options":["A higher commission","Reaching a minimum sales target","Opening an office in Berlin"],"a":1}],"gaps":[{"s":"Twenty-five percent is a bit ___ for us.","a":"high","hint":"yüksek"},{"s":"What if we meet in the ___ at 20 percent?","a":"middle","hint":"orta"},{"s":"I think we've reached an ___.","a":"agreement","hint":"anlaşma"}],"order":[{"a":"We can review the agreement after twelve months."},{"a":"Let's put everything in writing and sign next week."}],"translate":[{"tr":"Teklif için teşekkürler ama bu bizim için biraz yüksek.","en":"Thank you for the offer, but it's a bit high for us.","keys":["offer","a bit high"]},{"tr":"Sanırım bir anlaşmaya vardık.","en":"I think we've reached an agreement.","keys":["reached an agreement"]}],"roleplay":{"persona":"Distributor","personaTr":"Distribütör","scene":"Almanya'da satış yapmak isteyen Hollandalı bir distribütör, komisyon oranı ve münhasırlık konusunda pazarlık yapıyor.","turns":[{"ai":"Our standard commission is 25 percent. Can you accept that?","aiTr":"Standart komisyonumuz yüzde 25. Bunu kabul edebilir misiniz?","hint":"Thank you for the offer, but 25 percent is a bit high for us. We can't go above 15 percent.","keys":["a bit high","offer","15 percent"]},{"ai":"I'm afraid that won't work for us; we have marketing costs too.","aiTr":"Korkarım bu bizim için olmaz; bizim de pazarlama masraflarımız var.","hint":"I understand, so what if we meet in the middle at 20 percent for the first year?","keys":["meet in the middle","what if","20 percent"]},{"ai":"And what happens after the first year?","aiTr":"Peki ilk yıldan sonra ne olacak?","hint":"We can review the agreement after twelve months and adjust it if we need to.","keys":["review","twelve months","adjust"]},{"ai":"That sounds fair. We'd also like exclusive rights in Germany.","aiTr":"Bu adil görünüyor. Almanya'da münhasır haklar da istiyoruz.","hint":"We can agree to that, as long as you reach a minimum sales target.","keys":["as long as","sales target","minimum"]}]}},"st-05":{"intro":"Bir hastane şikayet ediyor. Özür dilemek, çözüm sunmak ve güveni korumak.","text":[{"en":"Yesterday, a hospital in Izmir called us with a complaint.","tr":"Dün İzmir'deki bir hastane bizi bir şikayetle aradı."},{"en":"Their device stopped working in the middle of a hearing test.","tr":"Cihazları bir işitme testinin ortasında çalışmayı durdurdu."},{"en":"The doctor was angry, and that's understandable, because she had a lot of patients waiting.","tr":"Doktor kızgındı; bu anlaşılır bir şey, çünkü bekleyen çok hastası vardı."},{"en":"First, I apologised and thanked her for letting us know so quickly.","tr":"Önce özür diledim ve bize bu kadar çabuk haber verdiği için teşekkür ettim."},{"en":"Then I asked a few questions to understand exactly what had happened.","tr":"Sonra tam olarak ne olduğunu anlamak için birkaç soru sordum."},{"en":"In the end, it turned out to be a software bug, not a hardware problem.","tr":"Sonunda bunun bir donanım sorunu değil, bir yazılım hatası olduğu ortaya çıktı."},{"en":"Our engineer sent an update within two hours, and the device started working again.","tr":"Mühendisimiz iki saat içinde bir güncelleme gönderdi ve cihaz yeniden çalışmaya başladı."},{"en":"I called the doctor back to make sure everything was fine.","tr":"Her şeyin yolunda olduğundan emin olmak için doktoru geri aradım."},{"en":"I've learned that a complaint doesn't have to be the end of a relationship.","tr":"Bir şikayetin bir ilişkinin sonu olmak zorunda olmadığını öğrendim."},{"en":"If you handle it well, it can actually make the relationship stronger.","tr":"İyi yönetirseniz, aslında ilişkiyi daha da güçlendirebilir."}],"vocab":[{"en":"complaint","tr":"şikayet","ex":"A hospital called us with a complaint.","def":"a statement that something is wrong or not good enough"},{"en":"apologise","tr":"özür dilemek","ex":"First, I apologised to the doctor.","def":"to say that you are sorry"},{"en":"let someone know","tr":"birine haber vermek","ex":"Thank you for letting us know so quickly.","def":"to tell someone about something"},{"en":"turn out to be","tr":"...olduğu ortaya çıkmak","ex":"It turned out to be a software bug.","def":"to be discovered to be something in the end"},{"en":"software bug","tr":"yazılım hatası","ex":"Our engineer found the software bug.","def":"a mistake in a computer program"},{"en":"within two hours","tr":"iki saat içinde","ex":"The update arrived within two hours.","def":"in less than two hours"},{"en":"make sure","tr":"emin olmak","ex":"I called back to make sure everything was fine.","def":"to check that something is true or has been done"},{"en":"handle a complaint","tr":"bir şikayeti yönetmek","ex":"If you handle a complaint well, customers trust you more.","def":"to deal with a customer's problem"}],"grammar":{"title":"Present perfect vs past simple","tr":"Belirli bir geçmiş zamandaki olay için past simple kullanılır (Yesterday a hospital called us). Bugüne etkisi olan deneyim ya da ders için present perfect kullanılır (I've learned that...).","examples":["Yesterday, a hospital called us with a complaint.","I've learned that a complaint is not the end.","Our engineer sent an update within two hours."]},"questions":[{"q":"Why was the doctor angry?","options":["The engineer was late","The device was too expensive","She had a lot of patients waiting"],"a":2},{"q":"What did the speaker do first?","options":["Apologised and thanked her","Sent an engineer to Izmir","Asked for a new contract"],"a":0},{"q":"What was the cause of the problem?","options":["A broken cable","A software bug","A mistake by the doctor"],"a":1},{"q":"What has the speaker learned?","options":["Complaints always end a relationship","Customers should not call so quickly","A complaint handled well can make a relationship stronger"],"a":2}],"gaps":[{"s":"First, I ___ and thanked her for letting us know.","a":"apologised","hint":"özür diledim"},{"s":"It turned ___ to be a software bug.","a":"out","hint":"ortaya çıktı"},{"s":"I called the doctor back to make ___ everything was fine.","a":"sure","hint":"emin olmak"}],"order":[{"a":"Our engineer sent an update within two hours."},{"a":"A complaint doesn't have to be the end."}],"translate":[{"tr":"Bize haber verdiğiniz için teşekkürler.","en":"Thank you for letting us know.","keys":["letting us know"]},{"tr":"Bir yazılım hatası olduğu ortaya çıktı.","en":"It turned out to be a software bug.","keys":["turned out","software bug"]}],"roleplay":{"persona":"Angry doctor","personaTr":"Kızgın doktor","scene":"İzmir'deki bir hastanenin doktoru, cihazın test sırasında durduğunu söylüyor.","turns":[{"ai":"Your device stopped in the middle of a test, and I have ten patients waiting!","aiTr":"Cihazınız bir testin ortasında durdu ve bekleyen on hastam var!","hint":"I'm really sorry about this. Thank you for letting us know so quickly. Can I ask you a few questions?","keys":["sorry","thank you","questions"]},{"ai":"The screen is black and it won't restart.","aiTr":"Ekran siyah ve yeniden başlamıyor.","hint":"I understand. It sounds like a software bug, so our engineer will send an update.","keys":["software bug","update","engineer"]},{"ai":"How long will that take? I can't wait all day.","aiTr":"Bu ne kadar sürer? Bütün gün bekleyemem.","hint":"It should be working again within two hours, and I'll call you back to make sure everything is fine.","keys":["two hours","call you back","make sure"]},{"ai":"Okay, but how do I know this won't happen again?","aiTr":"Tamam, ama bunun tekrar olmayacağını nereden bileceğim?","hint":"That's a fair question. We will find out why it happened, and I'll keep you updated.","keys":["find out","keep you updated","why"]}]}},"co-03":{"intro":"Farklı düşündüğünü kavga etmeden, net ve saygılı söylemek: fiyat tartışmasında ortağına karşı çıkıyorsun.","text":[{"who":"Partner","en":"I think we should lower the price to 2,000 euros so that we can sell faster.","tr":"Bence daha hızlı satabilmek için fiyatı 2.000 euroya düşürmeliyiz."},{"who":"Me","en":"I see your point, but I'm not sure that's the best way forward.","tr":"Ne demek istediğini anlıyorum ama bunun en doğru yol olduğundan emin değilim."},{"who":"Me","en":"The device costs 1,500 euros to make, so if we lower the price, our margin will become very small.","tr":"Cihazın üretimi 1.500 euro tutuyor, yani fiyatı düşürürsek marjımız çok küçülür."},{"who":"Partner","en":"But several customers have told us that the device is too expensive.","tr":"Ama birçok müşteri bize cihazın çok pahalı olduğunu söyledi."},{"who":"Me","en":"That's true; however, I think the real problem is that they don't see the value yet.","tr":"Doğru; ancak bence asıl sorun, değerini henüz görmemeleri."},{"who":"Me","en":"We should show them how much money they can save every month.","tr":"Onlara her ay ne kadar para tasarruf edebileceklerini göstermeliyiz."},{"who":"Partner","en":"Hmm, that's a fair point, but how would we do that?","tr":"Hmm, haklı bir nokta ama bunu nasıl yaparız?"},{"who":"Me","en":"We could prepare a simple calculator: \"If you do 100 tests a month, you save 1,500 euros.\"","tr":"Basit bir hesaplayıcı hazırlayabiliriz: \"Ayda 100 test yaparsanız 1.500 euro tasarruf edersiniz.\""},{"who":"Partner","en":"OK, let's try that for two months before we change the price.","tr":"Tamam, fiyatı değiştirmeden önce bunu iki ay deneyelim."},{"who":"Me","en":"Agreed, and thanks for listening.","tr":"Anlaştık, dinlediğin için de teşekkürler."}],"vocab":[{"en":"lower the price","tr":"fiyatı düşürmek","ex":"We should lower the price to sell faster.","def":"to make something cheaper"},{"en":"I see your point, but...","tr":"Ne demek istediğini anlıyorum ama...","ex":"I see your point, but I'm not sure it's the best way.","def":"a polite way to start disagreeing with someone"},{"en":"margin","tr":"kâr marjı","ex":"If we lower the price, our margin will become very small.","def":"the money left after you pay the cost of making a product"},{"en":"however","tr":"ancak, fakat","ex":"That's true; however, the real problem is the value.","def":"a word that introduces a different or opposite idea"},{"en":"value","tr":"değer","ex":"Customers don't see the value yet.","def":"how useful or important something is for someone"},{"en":"a fair point","tr":"haklı bir nokta","ex":"Hmm, that's a fair point.","def":"an idea that is reasonable and that you accept"},{"en":"prepare","tr":"hazırlamak","ex":"We could prepare a simple calculator.","def":"to make something ready to use"},{"en":"Agreed.","tr":"Anlaştık.","ex":"Agreed, let's try it for two months.","def":"a short way to say 'I agree'"}],"grammar":{"title":"First conditional: If we..., ... will...","tr":"Gerçek bir olasılık ve sonucu için kullanılır: If + geniş zaman, will + fiil. Toplantıda bir önerinin sonucunu göstermek için çok işe yarar.","examples":["If we lower the price, our margin will become very small.","If customers see the value, they will pay.","If the calculator works, we won't change the price."]},"questions":[{"q":"What does the partner want to do?","options":["Raise the price","Lower the price to 2,000 euros","Give the device for free"],"a":1},{"q":"Why does the speaker disagree?","options":["The margin will become very small","Customers don't like the design","The team is too small"],"a":0},{"q":"According to the speaker, what is the real problem?","options":["The price","The calculator","Customers don't see the value yet"],"a":2},{"q":"What do they decide in the end?","options":["To lower the price now","To try the calculator for two months","To stop selling the device"],"a":1}],"gaps":[{"s":"I see your ___, but I'm not sure that's the best way forward.","a":"point","hint":"görüş, nokta"},{"s":"If we lower the price, our ___ will become very small.","a":"margin","hint":"kâr marjı"},{"s":"Hmm, that's a ___ point.","a":"fair","hint":"haklı, makul"}],"order":[{"a":"I'm not sure that's the best way forward."},{"a":"We should show them how much money they can save."}],"translate":[{"tr":"Bence asıl sorun fiyat değil.","en":"I don't think the price is the real problem.","keys":["real problem","price"]},{"tr":"Fiyatı değiştirmeden önce bunu iki ay deneyelim.","en":"Let's try this for two months before we change the price.","keys":["two months","change the price"]}],"roleplay":{"persona":"Business partner","personaTr":"İş ortağı","scene":"Ortağın cihazı ücretsiz vermeyi öneriyor; sen nazikçe karşı çıkıp bir deneme öneriyorsun.","turns":[{"ai":"I think we should give the device away for free and only charge for the software.","aiTr":"Bence cihazı ücretsiz verip sadece yazılım için ücret almalıyız.","hint":"I see your point, but I'm not sure that's the best way. The device costs us 1,500 euros to make.","keys":["see your point","not sure","costs"]},{"ai":"But customers would love a free device!","aiTr":"Ama müşteriler ücretsiz bir cihaza bayılır!","hint":"That's true. However, if we do that, we'll have to charge a much higher software fee.","keys":["however","software fee","have to"]},{"ai":"OK, that's a fair point. So what do you suggest?","aiTr":"Tamam, haklı bir nokta. Peki ne öneriyorsun?","hint":"I suggest we test both models with a few clinics for two months. Agreed?","keys":["suggest","test","two months","agreed"]}]}},"in-01":{"intro":"Kısa bir yatırımcı sunumunun yapısını öğreniyorsun: sorun, çözüm, pazar, ekip ve talep.","text":[{"who":"Me","en":"Hello everyone, my name is {name}, and I'm the founder of AIHEAR.","tr":"Herkese merhaba, benim adım {name} ve AIHEAR'ın kurucusuyum."},{"who":"Me","en":"Here's the problem: one in five people has some hearing loss, but most of them are never tested.","tr":"Sorun şu: her beş kişiden biri bir ölçüde işitme kaybı yaşıyor, ama çoğu hiç test edilmiyor."},{"who":"Me","en":"That's because a hearing test needs an expert, and in small towns people wait months to see one.","tr":"Çünkü işitme testi bir uzman gerektiriyor ve küçük şehirlerde insanlar bir uzmana görünmek için aylarca bekliyor."},{"who":"Me","en":"Our solution is an autonomous audiometer that does the whole test by itself in under ten minutes.","tr":"Çözümümüz, tüm testi on dakikadan kısa sürede kendi kendine yapan otonom bir odyometre."},{"who":"Me","en":"Our customers are hospitals, clinics and hearing aid shops, and the market is huge.","tr":"Müşterilerimiz hastaneler, klinikler ve işitme cihazı mağazaları; pazar ise devasa."},{"who":"Me","en":"Our business model is simple: we sell the device and charge a monthly software fee.","tr":"İş modelimiz basit: cihazı satıyoruz ve aylık bir yazılım ücreti alıyoruz."},{"who":"Me","en":"So far, we've built a working prototype and signed five paying customers.","tr":"Şimdiye kadar çalışan bir prototip geliştirdik ve beş ödeme yapan müşteriyle anlaştık."},{"who":"Me","en":"Our team of six includes three engineers, a doctor and two business people.","tr":"Altı kişilik ekibimizde üç mühendis, bir doktor ve iki iş insanı var."},{"who":"Me","en":"We're raising 500,000 euros to complete certification and enter the European market.","tr":"Sertifikasyonu tamamlamak ve Avrupa pazarına girmek için 500.000 euro yatırım topluyoruz."},{"who":"Me","en":"Thank you, and I'm happy to answer your questions.","tr":"Teşekkürler, sorularınızı yanıtlamaktan memnuniyet duyarım."}],"vocab":[{"en":"founder","tr":"kurucu","ex":"I'm the founder of AIHEAR.","def":"the person who starts a company"},{"en":"one in five","tr":"her beş kişiden biri","ex":"One in five people has some hearing loss.","def":"20 percent of a group"},{"en":"autonomous","tr":"otonom, kendi kendine çalışan","ex":"Our audiometer is autonomous.","def":"able to work by itself"},{"en":"business model","tr":"iş modeli","ex":"Our business model is simple.","def":"the way a company makes money"},{"en":"charge a fee","tr":"ücret almak","ex":"We charge a monthly software fee.","def":"to ask for money for a product or service"},{"en":"sign a customer","tr":"bir müşteriyle anlaşmak","ex":"We've signed five paying customers.","def":"to get a customer to agree to buy"},{"en":"raise (money)","tr":"yatırım toplamak","ex":"We're raising 500,000 euros.","def":"to get money from investors"},{"en":"enter the market","tr":"pazara girmek","ex":"We want to enter the European market.","def":"to start selling in a new place"}],"grammar":{"title":"Present perfect: what we have achieved","tr":"Present perfect (have/has + V3), sonucu bugün önemli olan başarıları anlatmak için kullanılır; 'so far' ve 'already' ile sık görülür. Yatırımcıya ilerlemeni göstermenin en doğal yolu budur.","examples":["So far, we've built a working prototype.","We've signed five paying customers.","Have you tested it in hospitals?"]},"questions":[{"q":"Why are most people with hearing loss never tested?","options":["Tests are too expensive","Tests need an expert, and there aren't enough","People don't care"],"a":1},{"q":"Who are the customers?","options":["Hospitals, clinics and hearing aid shops","Only patients","Schools and universities"],"a":0},{"q":"How many people are in the team?","options":["Three","Ten","Six"],"a":2},{"q":"How much are they raising?","options":["50,000 euros","500,000 euros","5 million euros"],"a":1}],"gaps":[{"s":"I'm the ___ of AIHEAR.","a":"founder","hint":"kurucu"},{"s":"Our business ___ is simple.","a":"model","hint":"model"},{"s":"We're ___ 500,000 euros to complete certification.","a":"raising","hint":"topluyoruz"}],"order":[{"a":"So far we've built a working prototype."},{"a":"Our team includes three engineers and a doctor."}],"translate":[{"tr":"Çözümümüz otonom bir odyometre.","en":"Our solution is an autonomous audiometer.","keys":["solution","autonomous audiometer"]},{"tr":"Sorularınızı yanıtlamaktan memnuniyet duyarım.","en":"I'm happy to answer your questions.","keys":["happy to answer","questions"]}],"roleplay":{"persona":"Investor at a demo day","personaTr":"Demo günü yatırımcısı","scene":"Sunumun bitti. Yatırımcı dört soru soruyor.","turns":[{"ai":"Good pitch. In one sentence: what problem do you solve?","aiTr":"İyi sunum. Tek cümleyle: çözdüğünüz sorun ne?","hint":"One in five people has hearing loss, but most are never tested because there aren't enough experts.","keys":["hearing loss","never tested","experts","one in five"]},{"ai":"How do you make money?","aiTr":"Nasıl para kazanıyorsunuz?","hint":"We sell the device and charge a monthly software fee.","keys":["sell","fee","monthly"]},{"ai":"What have you achieved so far?","aiTr":"Şimdiye kadar neler başardınız?","hint":"We've built a working prototype and signed five paying customers.","keys":["working prototype","five paying customers","signed"]},{"ai":"How much are you raising, and what for?","aiTr":"Ne kadar topluyorsunuz ve ne için?","hint":"We're raising 500,000 euros to complete certification and enter the European market.","keys":["raising","certification","European market"]}]}},"ai-03":{"intro":"Prototip, geliştirme aşamaları ve sonraki adımlar için sunum dili.","text":[{"en":"Thank you for your time; let me show you our prototype.","tr":"Zamanınız için teşekkürler; size prototipimizi göstereyim."},{"en":"We are developing an AI-assisted audiometer that aims to make hearing tests more accessible and efficient.","tr":"İşitme testlerini daha erişilebilir ve verimli hâle getirmeyi amaçlayan, yapay zekâ destekli bir odyometre geliştiriyoruz."},{"en":"Our goal is to simplify the testing process while maintaining reliable results.","tr":"Amacımız, güvenilir sonuçları korurken test sürecini basitleştirmek."},{"en":"This is the third version of the prototype, and the first one was just a laptop and headphones.","tr":"Bu prototipin üçüncü versiyonu; ilki sadece bir dizüstü bilgisayar ve kulaklıktı."},{"en":"We have completed the main development phase.","tr":"Ana geliştirme aşamasını tamamladık."},{"en":"We have also tested the device in a clinical study with 200 participants at two university hospitals.","tr":"Ayrıca cihazı iki üniversite hastanesinde 200 katılımcıyla yapılan bir klinik çalışmada test ettik."},{"en":"Its results matched those of a trained audiologist in 94% of cases.","tr":"Sonuçları, vakaların %94'ünde eğitimli bir odyoloğun sonuçlarıyla eşleşti."},{"en":"Now we are focusing on certification and the final product design.","tr":"Şimdi sertifikasyona ve nihai ürün tasarımına odaklanıyoruz."},{"en":"We are raising €500,000 to get the CE mark and enter the European market.","tr":"CE işaretini almak ve Avrupa pazarına girmek için 500.000 € yatırım topluyoruz."},{"en":"If everything goes to plan, we should have the CE mark by the end of next year.","tr":"Her şey plana göre giderse, gelecek yılın sonuna kadar CE işaretini almış olmalıyız."}],"vocab":[{"en":"aim to","tr":"amaçlamak","ex":"We aim to make hearing tests accessible.","def":"to plan or try to achieve something"},{"en":"simplify","tr":"basitleştirmek","ex":"We want to simplify the testing process.","def":"to make something easier to do or understand"},{"en":"maintain reliable results","tr":"güvenilir sonuçları korumak","ex":"We simplify the test while maintaining reliable results.","def":"to keep results accurate and trustworthy"},{"en":"development phase","tr":"geliştirme aşaması","ex":"We have completed the main development phase.","def":"a stage in building a product"},{"en":"clinical study","tr":"klinik çalışma","ex":"We ran a clinical study with 200 participants.","def":"research that tests a medical product on people"},{"en":"focus on","tr":"...e odaklanmak","ex":"Now we are focusing on certification.","def":"to give most of your attention to something"},{"en":"enter a market","tr":"bir pazara girmek","ex":"We want to enter the European market.","def":"to start selling in a new region or area"},{"en":"go to plan","tr":"plana göre gitmek","ex":"If everything goes to plan, we will have the CE mark next year.","def":"to happen in the way that was intended"}],"grammar":{"title":"Present perfect: results so far","tr":"Sonucu bugün önemli olan tamamlanmış işler için present perfect (have + V3) kullanılır: We have completed... Belirli bir geçmiş zaman ya da bitmiş durum için past simple kullanılır: The first one was a laptop.","examples":["We have completed the main development phase.","We have tested the device in a clinical study.","The first one was just a laptop and headphones."]},"questions":[{"q":"What is the goal of the product?","options":["To replace doctors completely","To simplify the test while keeping reliable results","To make cheaper headphones"],"a":1},{"q":"What was the first prototype?","options":["A laptop and headphones","A phone app","A big hospital machine"],"a":0},{"q":"How often did the device's results match a trained audiologist?","options":["In 64% of cases","In 84% of cases","In 94% of cases"],"a":2},{"q":"What will the €500,000 be used for?","options":["Buying a building","Getting the CE mark and entering the European market","Opening an office in London"],"a":1}],"gaps":[{"s":"We have completed the main development ___.","a":"phase","hint":"aşama"},{"s":"Now we are focusing ___ certification.","a":"on","hint":"focus ___ (odaklanmak)"},{"s":"If everything goes to ___, we should have the CE mark by the end of next year.","a":"plan","hint":"plan"}],"order":[{"a":"Our goal is to simplify the testing process."},{"a":"We have completed the main development phase."}],"translate":[{"tr":"Amacımız işitme testlerini daha erişilebilir hâle getirmek.","en":"Our goal is to make hearing tests more accessible.","keys":["goal","accessible"]},{"tr":"Şimdi sertifikasyona odaklanıyoruz.","en":"Now we are focusing on certification.","keys":["focusing on","certification"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Londra'da bir sağlık teknolojisi yatırımcısı prototipini görmek istiyor.","turns":[{"ai":"Thanks for coming. What exactly are you developing?","aiTr":"Geldiğiniz için teşekkürler. Tam olarak ne geliştiriyorsunuz?","hint":"We are developing an AI-assisted audiometer that aims to make hearing tests more accessible and efficient.","keys":["audiometer","accessible","efficient"]},{"ai":"What stage are you at right now?","aiTr":"Şu anda hangi aşamadasınız?","hint":"We have completed the main development phase, and now we are focusing on certification.","keys":["completed","development phase","certification"]},{"ai":"Do you have any data from real patients?","aiTr":"Gerçek hastalardan veriniz var mı?","hint":"Yes, in a clinical study with 200 participants, our results matched a trained audiologist in 94% of cases.","keys":["200","94","matched"]},{"ai":"And what will you do with my money?","aiTr":"Peki paramla ne yapacaksınız?","hint":"We will use the €500,000 to get the CE mark and enter the European market.","keys":["CE mark","European market","500"]}]}},"in-02":{"intro":"Gelir, maliyet, kâr marjı ve tekrarlayan gelir kavramlarını kullanarak iş modelini anlatıyorsun.","text":[{"who":"Me","en":"Investors always ask the same question: how do you make money?","tr":"Yatırımcılar hep aynı soruyu sorar: Nasıl para kazanıyorsunuz?"},{"who":"Me","en":"We have two sources of revenue: the device and the software.","tr":"İki gelir kaynağımız var: cihaz ve yazılım."},{"who":"Me","en":"We sell the device for 4,000 euros, and it costs us 1,500 euros to produce.","tr":"Cihazı 4.000 euroya satıyoruz ve üretmesi bize 1.500 euroya mal oluyor."},{"who":"Me","en":"That means our gross margin on each device is about 60 percent.","tr":"Bu, her cihazdaki brüt kâr marjımızın yaklaşık yüzde 60 olduğu anlamına geliyor."},{"who":"Me","en":"On top of that, every clinic pays a software fee of 99 euros a month.","tr":"Bunun yanında her klinik ayda 99 euro yazılım ücreti ödüyor."},{"who":"Me","en":"This is recurring revenue, and investors love it because it comes in every month.","tr":"Bu tekrarlayan gelir ve yatırımcılar buna bayılır, çünkü her ay düzenli olarak gelir."},{"who":"Me","en":"If we reach 1,000 clinics, the software alone will bring in about 1.2 million euros a year.","tr":"1.000 kliniğe ulaşırsak yalnızca yazılım yılda yaklaşık 1,2 milyon euro getirecek."},{"who":"Me","en":"So far, we've signed five paying customers, so there's still a long way to go.","tr":"Şimdiye kadar beş ödeme yapan müşteriyle anlaştık, yani daha gidecek uzun bir yolumuz var."},{"who":"Me","en":"Our biggest costs are salaries, certification and marketing.","tr":"En büyük maliyetlerimiz maaşlar, sertifikasyon ve pazarlama."},{"who":"Me","en":"However, we expect to be profitable in our third year.","tr":"Yine de üçüncü yılımızda kârlı olmayı bekliyoruz."}],"vocab":[{"en":"make money","tr":"para kazanmak","ex":"How do you make money?","def":"to earn money from a business"},{"en":"revenue","tr":"gelir, ciro","ex":"We have two sources of revenue.","def":"the money a company receives from sales"},{"en":"cost (to produce)","tr":"üretim maliyeti","ex":"It costs us 1,500 euros to produce.","def":"the money needed to make one product"},{"en":"gross margin","tr":"brüt kâr marjı","ex":"The gross margin is about 60 percent.","def":"the part of the price left after production costs"},{"en":"recurring revenue","tr":"tekrarlayan gelir","ex":"Software gives us recurring revenue.","def":"money that comes in regularly, for example every month"},{"en":"bring in","tr":"getirmek, kazandırmak","ex":"The software will bring in 1.2 million euros a year.","def":"to earn money"},{"en":"a long way to go","tr":"gidilecek uzun bir yol","ex":"We still have a long way to go.","def":"a lot of work still to do"},{"en":"profitable","tr":"kârlı","ex":"We expect to be profitable in our third year.","def":"making more money than you spend"}],"grammar":{"title":"First conditional: if + present, will","tr":"Gerçekleşmesi olası bir durumun sonucunu anlatmak için first conditional kullanılır: If + present simple, will + fiil. Yatırımcıya hedefleri ve sonuçlarını göstermek için idealdir.","examples":["If we reach 1,000 clinics, the software will bring in 1.2 million euros a year.","If we sell more devices, our revenue will grow.","What will happen if certification takes longer?"]},"questions":[{"q":"What are the two sources of revenue?","options":["Advertising and grants","The device and the software","Training and repairs"],"a":1},{"q":"What is the gross margin on the device?","options":["About 60 percent","About 10 percent","About 90 percent"],"a":0},{"q":"Why do investors love recurring revenue?","options":["It is very large","It is tax-free","It comes in every month"],"a":2},{"q":"When do they expect to be profitable?","options":["In the first year","In the third year","In the tenth year"],"a":1}],"gaps":[{"s":"We have two sources of ___.","a":"revenue","hint":"gelir"},{"s":"This is ___ revenue, and investors love it.","a":"recurring","hint":"tekrarlayan"},{"s":"We expect to be ___ in our third year.","a":"profitable","hint":"kârlı"}],"order":[{"a":"Every clinic pays a software fee of 99 euros a month."},{"a":"Our biggest costs are salaries and marketing."}],"translate":[{"tr":"Nasıl para kazanıyorsunuz?","en":"How do you make money?","keys":["make money"]},{"tr":"En büyük maliyetlerimiz maaşlar ve pazarlama.","en":"Our biggest costs are salaries and marketing.","keys":["biggest costs","salaries"]}],"roleplay":{"persona":"Angel investor","personaTr":"Melek yatırımcı","scene":"Bir melek yatırımcı rakamları ayrıntılı olarak soruyor.","turns":[{"ai":"Let's talk numbers. How do you make money?","aiTr":"Rakamları konuşalım. Nasıl para kazanıyorsunuz?","hint":"We have two sources of revenue: the device and a monthly software fee.","keys":["revenue","device","software fee"]},{"ai":"What's your margin on the device?","aiTr":"Cihazdaki marjınız ne?","hint":"We sell it for 4,000 euros and it costs 1,500 to produce, so the gross margin is about 60 percent.","keys":["gross margin","60 percent","costs"]},{"ai":"What happens if you reach 1,000 clinics?","aiTr":"1.000 kliniğe ulaşırsanız ne olur?","hint":"If we reach 1,000 clinics, the software alone will bring in about 1.2 million euros a year.","keys":["1.2 million","bring in","software alone"]},{"ai":"When will you be profitable?","aiTr":"Ne zaman kârlı olacaksınız?","hint":"We expect to be profitable in our third year. Our biggest costs are salaries and certification.","keys":["profitable","third year","costs"]}]}},"in-04":{"intro":"Rakipler, riskler ve 'neden siz?' sorularına sakin ve dürüst cevaplar veriyorsun.","text":[{"who":"Investor","en":"Who are your main competitors?","tr":"Başlıca rakipleriniz kimler?"},{"who":"Me","en":"There are big companies that make classic audiometers, but their devices still need an expert to run the test.","tr":"Klasik odyometre yapan büyük şirketler var ama onların cihazları testi yapmak için hâlâ bir uzmana ihtiyaç duyuyor."},{"who":"Me","en":"There are also some apps, but they aren't medical devices and they aren't certified.","tr":"Bazı uygulamalar da var ama bunlar tıbbi cihaz değil ve sertifikalı da değil."},{"who":"Investor","en":"So what stops a big company from simply copying you?","tr":"Peki büyük bir şirketin sizi basitçe kopyalamasını ne engelliyor?"},{"who":"Me","en":"We've trained our AI model on thousands of real tests, and that kind of data is hard to get.","tr":"Yapay zekâ modelimizi binlerce gerçek testle eğittik ve bu tür verileri elde etmek zor."},{"who":"Me","en":"On top of that, big companies move slowly, while we can move much faster.","tr":"Üstelik büyük şirketler yavaş hareket eder, biz ise çok daha hızlı hareket edebiliriz."},{"who":"Investor","en":"And what is the biggest risk for your company?","tr":"Peki şirketiniz için en büyük risk ne?"},{"who":"Me","en":"Honestly, the biggest risk is certification, because it can take longer than we plan.","tr":"Açıkçası en büyük risk sertifikasyon, çünkü planladığımızdan uzun sürebilir."},{"who":"Me","en":"That's why we've already started the process, and we work with an experienced consultant.","tr":"Bu yüzden sürece çoktan başladık ve deneyimli bir danışmanla çalışıyoruz."},{"who":"Investor","en":"That's a good answer, and I like founders who know their risks.","tr":"Bu iyi bir cevap; risklerini bilen kurucuları severim."}],"vocab":[{"en":"main competitor","tr":"başlıca rakip","ex":"Who are your main competitors?","def":"one of the most important companies you compete with"},{"en":"certified","tr":"sertifikalı","ex":"The apps aren't certified.","def":"officially approved as meeting a standard"},{"en":"stop someone from doing something","tr":"birinin bir şeyi yapmasını engellemek","ex":"What stops a big company from copying you?","def":"to make it impossible for someone to do something"},{"en":"train a model on","tr":"bir modeli ... ile eğitmek","ex":"We've trained our model on thousands of real tests.","def":"to teach an AI system by giving it examples"},{"en":"hard to get","tr":"elde etmesi zor","ex":"That kind of data is hard to get.","def":"difficult to find or collect"},{"en":"move slowly","tr":"yavaş hareket etmek","ex":"Big companies move slowly.","def":"to make decisions and changes slowly"},{"en":"take longer than planned","tr":"planlanandan uzun sürmek","ex":"Certification can take longer than planned.","def":"to need more time than you expected"},{"en":"experienced consultant","tr":"deneyimli danışman","ex":"We work with an experienced consultant.","def":"an expert adviser who has done this work many times"}],"grammar":{"title":"Present perfect: results that matter now","tr":"Geçmişte yapılmış ama sonucu şimdi önemli olan işler için 'have/has + V3' kullanılır. 'already' ve 'yet' ile sık görülür.","examples":["We've trained our AI model on thousands of real tests.","We've already started the certification process.","We haven't got the CE mark yet."]},"questions":[{"q":"Why are the apps not real competitors?","options":["They are too cheap","They are too slow","They aren't certified medical devices"],"a":2},{"q":"Why is it hard to copy the company?","options":["Its AI is trained on data that is hard to get","It has a patent in every country","It has a very big office"],"a":0},{"q":"What is the biggest risk?","options":["Marketing","Certification","Competition"],"a":1},{"q":"How does the investor feel about the answer?","options":["Worried","Bored","Happy with it"],"a":2}],"gaps":[{"s":"Who are your main ___?","a":"competitors","hint":"rakipler"},{"s":"Big companies move ___, while we can move much faster.","a":"slowly","hint":"yavaş"},{"s":"___, the biggest risk is certification.","a":"Honestly","hint":"açıkçası"}],"order":[{"a":"That kind of data is hard to get."},{"a":"It can take longer than we plan."}],"translate":[{"tr":"Biz çok daha hızlı hareket edebiliriz.","en":"We can move much faster.","keys":["move","faster"]},{"tr":"Deneyimli bir danışmanla çalışıyoruz.","en":"We work with an experienced consultant.","keys":["experienced","consultant"]}],"roleplay":{"persona":"Tough investor","personaTr":"Sert yatırımcı","scene":"Deneyimli bir yatırımcı en zor soruları soruyor.","turns":[{"ai":"Who are your competitors, and why are you better?","aiTr":"Rakipleriniz kimler ve neden daha iyisiniz?","hint":"Big companies make classic audiometers, but they still need an expert. Some apps exist, but they aren't certified.","keys":["audiometers","expert","certified","apps"]},{"ai":"A big company could copy you in six months. What then?","aiTr":"Büyük bir şirket sizi altı ayda kopyalayabilir. O zaman ne olacak?","hint":"We've trained our AI on thousands of real tests, and that data is hard to get. And we move faster.","keys":["trained","data","hard to get","faster"]},{"ai":"What keeps you awake at night? What is the biggest risk?","aiTr":"Sizi geceleri uyutmayan ne? En büyük risk ne?","hint":"Honestly, certification. It can take longer than we plan, so we've already started and we work with a consultant.","keys":["honestly","certification","longer","consultant"]}]}},"fu-02":{"intro":"Bir gazeteci seninle sağlık verilerinin etiği üzerine röportaj yapıyor; hasta hakları, onam, anonimleştirme ve GDPR hakkında konuşuyorsun.","text":[{"who":"Journalist","en":"Health data has become very valuable, so who should actually own it?","tr":"Sağlık verileri çok değerli hale geldi; peki aslında kime ait olmalı?"},{"who":"Me","en":"I believe patients should own their data and decide who can use it.","tr":"Bence hastalar verilerinin sahibi olmalı ve onları kimin kullanabileceğine kendileri karar vermeli."},{"who":"Me","en":"That's why informed consent is so important: people have to understand what we collect and why before they agree.","tr":"Bu yüzden bilgilendirilmiş onam çok önemli: insanlar onay vermeden önce neyi neden topladığımızı anlamak zorunda."},{"who":"Me","en":"They should also be able to change their mind later.","tr":"Ayrıca daha sonra fikirlerini değiştirebilmeleri gerekir."},{"who":"Me","en":"Before we use data for research, we anonymise it, so nobody can tell who the patient is.","tr":"Verileri araştırmada kullanmadan önce anonimleştiriyoruz, böylece kimse hastanın kim olduğunu anlayamıyor."},{"who":"Me","en":"In Europe, GDPR gives health data extra protection, and companies have to follow strict rules.","tr":"Avrupa'da GDPR sağlık verilerine ek koruma sağlıyor ve şirketler sıkı kurallara uymak zorunda."},{"who":"Me","en":"At AIHEAR, our AI runs on the device, so the test data stays in the clinic.","tr":"AIHEAR'da yapay zekâmız cihazın üzerinde çalışıyor, bu yüzden test verileri klinikte kalıyor."},{"who":"Journalist","en":"But if AI needs lots of data to improve, isn't that a problem for you?","tr":"Ama yapay zekâ gelişmek için çok veriye ihtiyaç duyuyorsa, bu sizin için bir sorun değil mi?"},{"who":"Me","en":"It's a real trade-off, because more data usually means better AI, but also more risk to privacy.","tr":"Bu gerçek bir ödünleşim, çünkü daha fazla veri genellikle daha iyi yapay zekâ demek, ama gizlilik için daha fazla risk de demek."},{"who":"Me","en":"In the end, we've chosen privacy, so we only use anonymised data from clinical studies where people gave consent.","tr":"Sonunda gizliliği seçtik; bu yüzden yalnızca katılımcıların onay verdiği klinik çalışmalardan gelen anonim verileri kullanıyoruz."}],"vocab":[{"en":"valuable","tr":"değerli","ex":"Health data has become very valuable.","def":"worth a lot of money or very useful"},{"en":"own","tr":"sahip olmak","ex":"Patients should own their data.","def":"to have something that belongs to you"},{"en":"informed consent","tr":"bilgilendirilmiş onam","ex":"Informed consent protects patients.","def":"agreement given after someone fully understands what will happen"},{"en":"change your mind","tr":"fikrini değiştirmek","ex":"Patients can change their mind later.","def":"to make a different decision from before"},{"en":"anonymise","tr":"anonimleştirmek","ex":"We anonymise the data before research.","def":"to remove details that show who a person is"},{"en":"follow the rules","tr":"kurallara uymak","ex":"Companies have to follow strict rules.","def":"to do what the rules say"},{"en":"trade-off","tr":"ödünleşim, denge","ex":"There is a trade-off between better AI and privacy.","def":"a balance between two good things that you cannot fully have at the same time"},{"en":"privacy","tr":"gizlilik, mahremiyet","ex":"We've chosen privacy over speed.","def":"the right to keep personal information to yourself"}],"grammar":{"title":"Present perfect for changes up to now","tr":"Geçmişte başlayıp bugüne etkisi süren değişimler ve sonuçlar için present perfect kullanılır: 'Health data has become valuable', 'we've chosen privacy'. Ne zaman olduğu söylenmez; sonuç önemlidir.","examples":["Health data has become very valuable.","In the end, we've chosen privacy.","Every participant has given consent."]},"questions":[{"q":"Who does the speaker think should own health data?","options":["The company","Patients","Hospitals","The government"],"a":1},{"q":"What does informed consent mean here?","options":["People agree after they understand what is collected and why","People pay for their data","Doctors decide for patients"],"a":0},{"q":"Where does AIHEAR's test data stay?","options":["On the company's servers","In the cloud","In the clinic"],"a":2},{"q":"What is the trade-off the speaker mentions?","options":["Speed versus price","Better AI versus more risk to privacy","Doctors versus machines"],"a":1}],"gaps":[{"s":"Patients should own their data and ___ who can use it.","a":"decide","hint":"karar vermek"},{"s":"Before we use data for research, we ___ it.","a":"anonymise","hint":"anonimleştirmek"},{"s":"It's a real ___, because more data means better AI but more risk.","a":"trade-off","hint":"ödünleşim"}],"order":[{"a":"Patients should own their data."},{"a":"The test data stays in the clinic."}],"translate":[{"tr":"Hastalar daha sonra fikirlerini değiştirebilmeli.","en":"Patients should be able to change their mind later.","keys":["change their mind","later"]},{"tr":"Avrupa'da şirketler sıkı kurallara uymak zorunda.","en":"In Europe, companies have to follow strict rules.","keys":["have to follow","strict rules"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir sağlık teknolojisi dergisinden bir gazeteci, sağlık verilerinin etiği hakkında seninle röportaj yapıyor.","turns":[{"ai":"In your opinion, who should own a patient's health data?","aiTr":"Sizce bir hastanın sağlık verileri kime ait olmalı?","hint":"I believe patients should own their data and decide who can use it.","keys":["patients should own","decide","their data"]},{"ai":"How do patients know what happens to their data?","aiTr":"Hastalar verilerine ne olduğunu nasıl biliyor?","hint":"Through informed consent: we explain what we collect and why, and they can change their mind later.","keys":["informed consent","explain","change their mind"]},{"ai":"Does your device send data to the cloud?","aiTr":"Cihazınız verileri buluta gönderiyor mu?","hint":"No, our AI runs on the device, so the test data stays in the clinic.","keys":["runs on the device","stays in the clinic"]},{"ai":"But won't your AI be worse with less data?","aiTr":"Ama daha az veriyle yapay zekânız daha kötü olmaz mı?","hint":"It's a trade-off, but we've chosen privacy and only use anonymised data from people who gave consent.","keys":["trade-off","privacy","anonymised","consent"]}]}},"in-03":{"intro":"Hisse oranı, şirket değerlemesi ve yatırım sonrası değer gibi temel kavramlarla bir teklif üzerine pazarlık ediyorsun.","text":[{"who":"Investor","en":"We really like what you're building, and we'd like to make you an offer.","tr":"Geliştirdiğiniz şeyi gerçekten beğeniyoruz ve size bir teklif yapmak istiyoruz."},{"who":"Investor","en":"We can invest €500,000 for 25 percent equity.","tr":"Yüzde 25 hisse karşılığında 500.000 euro yatırım yapabiliriz."},{"who":"Me","en":"Thank you, so that means a post-money valuation of two million euros, right?","tr":"Teşekkürler, yani bu yatırım sonrası iki milyon euroluk bir değerleme demek, değil mi?"},{"who":"Me","en":"To be honest, we think the company is worth more than that.","tr":"Açıkçası şirketin bundan daha değerli olduğunu düşünüyoruz."},{"who":"Me","en":"We have a working product, five paying customers and strong results from our clinical study.","tr":"Çalışan bir ürünümüz, ödeme yapan beş müşterimiz ve klinik çalışmamızdan güçlü sonuçlarımız var."},{"who":"Me","en":"That's why we're looking for a valuation of around three million.","tr":"Bu yüzden üç milyon civarında bir değerleme arıyoruz."},{"who":"Investor","en":"Three million is high for a company that hasn't received its CE mark yet.","tr":"Henüz CE işaretini almamış bir şirket için üç milyon yüksek."},{"who":"Me","en":"I understand the risk, so what about 2.5 million post-money, with 20 percent equity?","tr":"Riski anlıyorum; o zaman yüzde 20 hisseyle, yatırım sonrası 2,5 milyona ne dersiniz?"},{"who":"Investor","en":"We can accept that if we get a seat on the board.","tr":"Yönetim kurulunda bir koltuk alırsak bunu kabul edebiliriz."},{"who":"Me","en":"A board seat is fine, because we want an active investor, not just money.","tr":"Yönetim kurulu koltuğu uygun, çünkü sadece para değil, aktif bir yatırımcı istiyoruz."}],"vocab":[{"en":"make an offer","tr":"teklif yapmak","ex":"We'd like to make you an offer.","def":"to say what you are ready to pay or give"},{"en":"equity","tr":"hisse, öz sermaye payı","ex":"They want 25 percent equity.","def":"a share of ownership in a company"},{"en":"post-money valuation","tr":"yatırım sonrası değerleme","ex":"That means a post-money valuation of two million euros.","def":"what a company is worth just after new investment comes in"},{"en":"be worth more","tr":"daha değerli olmak","ex":"We think the company is worth more than that.","def":"to have a higher value"},{"en":"paying customer","tr":"ödeme yapan müşteri","ex":"We have five paying customers.","def":"a customer who already buys your product"},{"en":"look for","tr":"aramak, hedeflemek","ex":"We're looking for a valuation of around three million.","def":"to try to find or get something"},{"en":"a seat on the board","tr":"yönetim kurulunda koltuk","ex":"The investor wants a seat on the board.","def":"a place in the group that makes the big decisions in a company"},{"en":"active investor","tr":"aktif yatırımcı","ex":"We want an active investor, not just money.","def":"an investor who helps the company, not only gives money"}],"grammar":{"title":"First conditional: if + present, can/will","tr":"Gerçekleşmesi olası bir koşulu anlatmak için 'if + geniş zaman' ve ana cümlede 'will' veya 'can' kullanılır. Pazarlıkta şart koymak için idealdir.","examples":["We can accept that if we get a seat on the board.","If you invest €500,000, you will own 20 percent.","If certification takes longer, we will need more time."]},"questions":[{"q":"What is the investor's first offer?","options":["€500,000 for 10 percent equity","€1 million for 50 percent equity","€500,000 for 25 percent equity"],"a":2},{"q":"What valuation does the founder ask for first?","options":["Two million","Around three million","Five million"],"a":1},{"q":"Why does the investor think three million is high?","options":["The company doesn't have its CE mark yet","The team is too small","The company has no customers"],"a":0},{"q":"What do they agree on in the end?","options":["€2 million post-money for 25 percent","€2.5 million post-money for 20 percent","€3 million post-money for 15 percent"],"a":1}],"gaps":[{"s":"We can invest €500,000 for 25 percent ___.","a":"equity","hint":"hisse"},{"s":"That means a post-money ___ of two million euros.","a":"valuation","hint":"değerleme"},{"s":"We think the company is ___ more than that.","a":"worth","hint":"değerinde"}],"order":[{"a":"We are looking for a valuation of around three million."},{"a":"We can accept that if we get a seat on the board."}],"translate":[{"tr":"Riski anlıyorum.","en":"I understand the risk.","keys":["understand","risk"]},{"tr":"Bunu kabul edebiliriz.","en":"We can accept that.","keys":["accept"]}],"roleplay":{"persona":"Venture capital investor","personaTr":"Risk sermayesi yatırımcısı","scene":"Bir VC fonu teklif yapıyor; değerleme üzerine pazarlık ediyorsun.","turns":[{"ai":"We can offer €500,000 for 25 percent of the company.","aiTr":"Şirketin yüzde 25'i için 500.000 euro teklif edebiliriz.","hint":"Thank you. That means a post-money valuation of two million, but we think the company is worth more.","keys":["valuation","worth more","two million"]},{"ai":"Why do you think it's worth more?","aiTr":"Neden daha değerli olduğunu düşünüyorsunuz?","hint":"We have a working product, five paying customers and strong clinical results.","keys":["working product","paying customers","clinical"]},{"ai":"So what valuation are you looking for?","aiTr":"Peki nasıl bir değerleme arıyorsunuz?","hint":"We're looking for around three million, but we could accept 2.5 million for 20 percent.","keys":["looking for","2.5 million","20 percent"]},{"ai":"We can do that if we get a seat on the board.","aiTr":"Yönetim kurulunda bir koltuk alırsak bunu yapabiliriz.","hint":"A board seat is fine. We want an active investor, not just money.","keys":["board seat","fine","active investor"]}]}}};
